    if os.path.exists("/tmp/tmp"): shutil.rmtree("/tmp/tmp")
    r=subprocess.run([EXE,"-q","80","-R","-S","-o","/tmp/out2","--verbose","3","--threads","2"]+files, capture_output=True, text=True, timeout=30, cwd=cwd)
