import subprocess, shutil, os, struct
EXE="/workspace/executable"
def parse_png(p):
    d=open(p,"rb").read()
    if d[:8]==b'\x89PNG\r\n\x1a\n': return ("png", struct.unpack(">II", d[16:24]))
    return None
def parse_jpg(p):
    d=open(p,"rb").read(); i=2
    while i<len(d)-9:
        if d[i]!=0xFF: i+=1; continue
        m=d[i+1]
        if m in (0xC0,0xC1,0xC2): return ("jpg", struct.unpack(">HH", d[i+5:i+9]), hex(m)) # h,w
        if m in (0xD8,): i+=2; continue
        if i+4>len(d): break
        ln=struct.unpack(">H", d[i+2:i+4])[0]; i+=2+ln
        if m==0xDA: break
    return ("jpg",None)
def parse_gif(p):
    d=open(p,"rb").read(); return ("gif", struct.unpack("<HH", d[6:10]))
def parse_webp(p):
    d=open(p,"rb").read()
    # VP8X, VP8 , VP8L ?
    print(" webp hdr", d[12:20])
    if d[12:16]==b'VP8 ':
        return ("webp", (struct.unpack("<H", d[26:28])[0]&0x3fff, struct.unpack("<H", d[28:30])[0]&0x3fff))
    if d[12:16]==b'VP8L':
        b=d[21:25]; w=1+ (b[0]|((b[1]&0x3f)<<8)); h=1+(((b[1]>>6)|(b[2]<<2)|((b[3]&0x0f)<<12))); return ("webpL",(w,h))
    if d[12:16]==b'VP8X':
        w=1+(d[24]|(d[25]<<8)|(d[26]<<16)); h=1+(d[27]|(d[28]<<8)|(d[29]<<16)); return ("webpX",(w,h))
    return ("webp?",d[12:16])
def dim(p):
    ext=os.path.splitext(p)[1].lower()
    try:
        if ext==".png": return parse_png(p)
        if ext in (".jpg",".jpeg",".JPG"): return parse_jpg(p)
        if ext==".gif": return parse_gif(p)
        if ext==".webp": return parse_webp(p)
    except Exception as e: return ("err",e)
    return None

def run(args, infile):
    shutil.rmtree("/tmp/out2",ignore_errors=True)
    r=subprocess.run([EXE]+args+["-o","/tmp/out2","--verbose","3",infile], capture_output=True, text=True, timeout=30)
