#include <stdint.h>
static void* H; static void* sym(const char*n){ void*p=dlsym(H,n); if(!p){fprintf(stderr,"no %s\n",n);exit(9);} return p;}
int main(){
 H=dlopen("/lib/x86_64-linux-gnu/libjpeg.so.8",RTLD_NOW);
 typedef void*(*se_t)(void*); typedef void(*cc_t)(void*,int,size_t); typedef void(*md_t)(void*,unsigned char**,unsigned long*); typedef void(*def_t)(void*); typedef void(*q_t)(void*,int,int); typedef void(*st_t)(void*,int); typedef unsigned int(*ws_t)(void*,unsigned char**,unsigned int); typedef void(*d_t)(void*);
 se_t se=(se_t)sym("jpeg_std_error"); cc_t cc=(cc_t)sym("jpeg_CreateCompress"); md_t md=(md_t)sym("jpeg_mem_dest"); def_t def=(def_t)sym("jpeg_set_defaults"); q_t sq=(q_t)sym("jpeg_set_quality"); st_t st=(st_t)sym("jpeg_start_compress"); ws_t ws=(ws_t)sym("jpeg_write_scanlines"); d_t fi=(d_t)sym("jpeg_finish_compress"); d_t de=(d_t)sym("jpeg_destroy_compress");
