 unsigned char img[3*4*3]; for(int i=0;i<36;i++) img[i]=i*7;
 for(int y=0;y<3;y++){ unsigned char*r=img+y*12; ws(c,&r,1);}
 fi(c); de(c); printf("outlen %lu magic %02x %02x\n",outlen,out[0],out[1]);
