fn def_by_id(id: DefId) -> &'static Def {
    DEFS.iter().find(|d| d.id == id).unwrap()
}
fn def_by_long(name: &str) -> Option<&'static Def> {
    DEFS.iter().find(|d| d.long == name)
}
fn def_by_short(c: char) -> Option<&'static Def> {
    DEFS.iter().find(|d| d.short == Some(c))
}
fn group_of(id: DefId) -> Option<u8> {
    match id {
        DefId::Quality | DefId::Lossless | DefId::MaxSize => Some(1),
        DefId::Output | DefId::SameFolder => Some(2),
        _ => None,
    }
}
fn group_render(g: u8) -> &'static str {
    match g {
        1 => "<--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>",
        _ => "<--output <OUTPUT>|--same-folder-as-input>",
    }
}
fn conflicts_with(a: DefId, b: DefId) -> bool {
    if a == b { return false; }
    if group_of(a).is_some() && group_of(a) == group_of(b) { return true; }
    use DefId::*;
    matches!(
        (a, b),
        (Width, LongEdge) | (Width, ShortEdge)
        | (Height, LongEdge) | (Height, ShortEdge)
        | (LongEdge, Width) | (LongEdge, Height) | (LongEdge, ShortEdge)
        | (ShortEdge, Width) | (ShortEdge, Height) | (ShortEdge, LongEdge)
        | (Quiet, Verbose) | (Verbose, Quiet)
    )
}

pub enum CliOutcome {
    Run(Box<Params>),
    Exit(i32),
}

struct Ctx {
    bin: String,
}

impl Ctx {
    fn usage_from_used(&self, used: &[DefId], has_files: bool) -> String {
        let mut tokens: Vec<String> = Vec::new();
        if used.is_empty() {
            tokens.push("[OPTIONS]".to_string());
        } else {
            let mut seen_groups: Vec<u8> = Vec::new();
            for id in used {
                if let Some(g) = group_of(*id) {
                    if !seen_groups.contains(&g) { seen_groups.push(g); }
                } else if *id == DefId::Files {
                    // handled at end
                } else {
                    tokens.push(def_by_id(*id).render.to_string());
                }
            }
        }
        tokens.push(group_render(1).to_string());
        tokens.push(group_render(2).to_string());
        tokens.push(if has_files { "<FILES>...".to_string() } else { "[FILES]...".to_string() });
        format!("Usage: {} {}", self.bin, tokens.join(" "))
    }
    fn generic_usage(&self) -> String {
        format!("Usage: {} [OPTIONS] {} {} [FILES]...", self.bin, group_render(1), group_render(2))
    }
    fn err_exit(&self, text: String) -> CliOutcome {
        eprint!("{}", text);
        CliOutcome::Exit(2)
    }
    fn err_no_usage(&self, msg: String) -> CliOutcome {
        self.err_exit(format!("error: {}\n\nFor more information, try '--help'.\n", msg))
    }
    fn err_with_usage(&self, msg: String, usage: String) -> CliOutcome {
        self.err_exit(format!("error: {}\n\n{}\n\nFor more information, try '--help'.\n", msg, usage))
    }
    fn invalid_value(&self, def: &Def, shown_value: &str, reason: Option<String>) -> CliOutcome {
        let argname = format!("--{} <{}>", def.long, def.value_name.unwrap_or(""));
        match (reason, def.possible) {
            (Some(r), _) => self.err_no_usage(format!("invalid value '{}' for '{}': {}", shown_value, argname, r)),
            (None, Some(vals)) => {
                let mut m = format!("invalid value '{}' for '{}'\n  [possible values: {}]\n", shown_value, argname, vals.join(", "));
                if let Some(sim) = did_you_mean(shown_value, vals) {
                    m.push_str(&format!("\n  tip: a similar value exists: '{}'\n", sim));
                }
                // err_no_usage adds prefix
                self.err_no_usage(m.trim_end_matches('\n').to_string())
            }
            (None, None) => self.err_no_usage(format!("invalid value '{}' for '{}'", shown_value, argname)),
        }
    }
    fn invalid_utf8(&self) -> CliOutcome {
        let u = self.generic_usage();
        self.err_with_usage("invalid UTF-8 was detected in one or more arguments".to_string(), u)
    }
    fn missing_value(&self, def: &Def) -> CliOutcome {
        let argname = format!("--{} <{}>", def.long, def.value_name.unwrap_or(""));
        let mut msg = format!("a value is required for '{}' but none was supplied", argname);
        if let Some(vals) = def.possible {
            msg.push_str(&format!("\n  [possible values: {}]", vals.join(", ")));
        }
        self.err_no_usage(msg)
    }
    fn multiple(&self, def: &Def) -> CliOutcome {
        let u = self.generic_usage();
        self.err_with_usage(format!("the argument '{}' cannot be used multiple times", def.render), u)
    }
}

// Jaro-Winkler implementation (for clap-like suggestions)
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    let match_dist = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_matched = vec![false; a.len()];
    let mut b_matched = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let lo = if i > match_dist { i - match_dist } else { 0 };
        let hi = (i + match_dist + 1).min(b.len());
        for j in lo..hi {
            if !b_matched[j] && a[i] == b[j] {
                a_matched[i] = true; b_matched[j] = true; matches += 1; break;
            }
        }
    }
    if matches == 0 { return 0.0; }
    let mut trans = 0usize;
    let mut j = 0usize;
    for i in 0..a.len() {
        if a_matched[i] {
            while !b_matched[j] { j += 1; }
            if a[i] != b[j] { trans += 1; }
            j += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (trans as f64) / 2.0) / m) / 3.0
}
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count().min(4);
    j + (prefix as f64 * 0.1 * (1.0 - j))
}
fn did_you_mean(v: &str, candidates: &[&str]) -> Option<String> {
    let mut scored: Vec<(f64, String)> = candidates.iter()
        .map(|c| (jaro_winkler(v, c), c.to_string()))
        .filter(|(conf, _)| *conf > 0.8)
        .collect();
    scored.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
    scored.into_iter().next().map(|(_, c)| c)
}
fn did_you_mean_long(v: &str) -> Option<String> {
    let candidates: Vec<&str> = DEFS.iter().map(|d| d.long).collect();
    did_you_mean(v, &candidates)
}

// ByteSize parsing (bytesize crate behaviour observed)
pub fn parse_bytesize(s: &str) -> Result<u64, String> {
    if let Ok(v) = s.parse::<u64>() { return Ok(v); }
    let num_end = s.char_indices().take_while(|(_, c)| c.is_ascii_digit() || *c == '.').map(|(i, c)| i + c.len_utf8()).last().unwrap_or(0);
    // take_while with char_indices: need length of prefix consisting of digits/dots from start (contiguous)
    let mut prefix_len = 0usize;
    for (i, c) in s.char_indices() {
        if c.is_ascii_digit() || c == '.' { prefix_len = i + c.len_utf8(); } else { break; }
    }
    let _ = num_end;
    let num_str = &s[..prefix_len];
    let value: f64 = match num_str.parse::<f64>() {
        Ok(v) => v,
        Err(e) => return Err(format!("couldn't parse \"{}\" into a ByteSize, {}", s, e)),
    };
    let unit_raw = &s[prefix_len..];
    let unit = unit_raw.trim_start();
    let mult: f64 = parse_unit(unit).ok_or_else(|| {
        let trunc = if unit.chars().count() > 3 {
            let t: String = unit.chars().take(3).collect();
            format!("{}...", t)
        } else { unit.to_string() };
        format!("couldn't parse \"{}\" into a known SI unit, Failed to parse unit \"{}\"", unit, trunc)
    })?;
    let bytes = value * mult;
    Ok(bytes as u64)
}
fn parse_unit(unit: &str) -> Option<f64> {
    let u = unit.to_uppercase();
    if u == "B" { return Some(1.0); }
    let mut chars = u.chars();
    let first = chars.next()?;
    let exp: u32 = match first {
        'K' => 1, 'M' => 2, 'G' => 3, 'T' => 4, 'P' => 5, 'E' => 6,
        _ => return None,
    };
    let rest: String = chars.collect();
    match rest.as_str() {
        "" | "B" => Some(1000f64.powi(exp as i32)),
        "I" | "IB" => Some(1024f64.powi(exp as i32)),
        _ => None,
    }
}

pub fn parse_max_size(s: &str) -> Result<u64, String> {
    parse_bytesize(s).map_err(|e| format!("Invalid size format: {}", e))
}

fn parse_quality(s: &str) -> Result<u32, String> {
    match s.parse::<u32>() {
        Ok(v) => {
            if v > 100 { Err(format!("Quality must be between 0 and 100, but got {}", v)) } else { Ok(v) }
        }
        Err(_) => Err(format!("'{}' is not a valid number", s)),
    }
}
fn parse_png_opt(s: &str) -> Result<u8, String> {
    match s.parse::<u8>() {
        Ok(v) => {
            if v > 6 { Err(format!("PNG optimization level must be between 0 and 6, but got {}", v)) } else { Ok(v) }
        }
        Err(_) => Err(format!("'{}' is not a valid number", s)),
    }
}
fn parse_verbose(s: &str) -> Result<u8, String> {
    match s.parse::<u8>() {
        Ok(v) => {
            if v > 3 { Err(format!("Verbosity must be between 0 and 3, but got {}", v)) } else { Ok(v) }
        }
        Err(_) => Err(format!("'{}' is not a valid number", s)),
    }
}
fn parse_u32_clap(s: &str) -> Result<u32, String> {
    match s.parse::<i64>() {
        Ok(v) => {
            if v < 0 || v > 4294967295 {
                Err(format!("{} is not in 0..=4294967295", v))
            } else { Ok(v as u32) }
        }
        Err(e) => Err(e.to_string()),
    }
}
fn parse_min_savings(s: &str) -> Result<MinSavings, String> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Err("Value cannot be empty. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes".to_string());
    }
    if trimmed.ends_with('%') {
        let perc_str = trimmed[..trimmed.len() - 1].trim();
        return match perc_str.parse::<f64>() {
            Ok(val) => {
                if !(0.0..=100.0).contains(&val) {
                    Err(format!("Percentage must be between 0 and 100, got {}", val))
                } else {
                    Ok(MinSavings::Percentage(val))
                }
            }
            Err(_) => Err(format!("Invalid percentage value: '{}'", perc_str)),
        };
    }
    if let Ok(v) = trimmed.parse::<u64>() {
        return Ok(MinSavings::Absolute(v));
    }
    if let Ok(v) = parse_bytesize(trimmed) {
        return Ok(MinSavings::Absolute(v));
    }
    Err(format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s))
}

fn is_empty_disallowed(id: DefId) -> bool {
