pub fn parse_cli() -> CliOutcome {
    let bin = bin_name();
    let ctx = Ctx { bin: bin.clone() };
    let argv: Vec<OsString> = std::env::args_os().skip(1).collect();
    let mut params = Params::default();
    let mut occs: Vec<Occ> = Vec::new();
    let mut seen: Vec<DefId> = Vec::new();
    let mut has_files = false;
    let mut positional_only = false;
    let mut i: usize = 0;

    macro_rules! record {
        ($id:expr) => {{
            if !seen.contains(&$id) { seen.push($id); }
            occs.push(Occ { id: $id });
        }};
    }

    // helper functions as closures not easy; inline code below
    while i < argv.len() {
        let arg_os = argv[i].clone();
        let bytes = arg_os.as_bytes();
        if positional_only {
            // file
            match arg_os.to_str() {
                None => return ctx.invalid_utf8(),
                Some(s) => {
                    if !seen.contains(&DefId::Files) { seen.push(DefId::Files); }
                    has_files = true;
                    params.files.push(s.to_string());
                }
            }
            i += 1;
            continue;
        }
        if bytes == b"--" {
            positional_only = true;
            i += 1;
            continue;
        }
        if bytes.len() >= 2 && &bytes[..2] == b"--" {
            // long
            let full = arg_os.to_string_lossy().to_string();
            let body = &full[2..];
            let (name_part, eq_val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            let def_opt = def_by_long(name_part);
            if def_opt.is_none() {
                // unknown long
                let shown = format!("--{}", name_part);
                let mut used: Vec<DefId> = Vec::new();
                for o in &occs { if !used.contains(&o.id) { used.push(o.id); } }
                let suggestion = did_you_mean_long(name_part);
                if let Some(ref sug) = suggestion {
                    if let Some(d) = def_by_long(sug) {
                        if !used.contains(&d.id) { used.push(d.id); }
                    }
                }
                let usage = ctx.usage_from_used(&used, has_files);
                let msg = if let Some(sug) = suggestion {
                    format!("unexpected argument '{}' found\n\n  tip: a similar argument exists: '--{}'", shown, sug)
                } else {
                    format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'", shown, shown, shown)
                };
                return ctx.err_with_usage(msg, usage);
            }
            let def = def_opt.unwrap();
            match def.id {
                DefId::Help | DefId::Version => {
                    if let Some(v) = eq_val {
                        let mut used: Vec<DefId> = Vec::new();
                        for o in &occs { if !used.contains(&o.id) { used.push(o.id); } }
                        if !used.contains(&def.id) { used.push(def.id); }
                        let usage = ctx.usage_from_used(&used, has_files);
                        return ctx.err_with_usage(format!("unexpected value '{}' for '{}' found; no more were expected", v, def.render), usage);
                    }
                    if def.id == DefId::Help {
                        // -h vs --help: need know which form was used: this is long -> long help
                        print!("{}", help_long(&bin));
                    } else {
                        println!("caesiumclt 1.3.0");
                    }
                    return CliOutcome::Exit(0);
                }
                _ => {}
            }
            if def.value_name.is_none() {
                // flag
                if let Some(v) = eq_val {
                    let mut used: Vec<DefId> = Vec::new();
                    for o in &occs { if !used.contains(&o.id) { used.push(o.id); } }
                    if !used.contains(&def.id) { used.push(def.id); }
                    let usage = ctx.usage_from_used(&used, has_files);
                    return ctx.err_with_usage(format!("unexpected value '{}' for '{}' found; no more were expected", v, def.render), usage);
                }
                if seen.contains(&def.id) {
                    return ctx.multiple(def);
                }
                record!(def.id);
                apply_flag(&mut params, def.id);
                i += 1;
                continue;
            } else {
                // value option
                let value_os: OsString;
                if let Some(v) = eq_val {
                    value_os = OsString::from(v);
                    i += 1;
                } else {
                    // lookahead
                    if i + 1 >= argv.len() {
                        return ctx.missing_value(def);
                    }
                    let next = argv[i + 1].clone();
                    let nb = next.as_bytes();
                    if nb == b"--" {
                        return ctx.missing_value(def);
                    }
                    if nb.len() > 1 && nb[0] == b'-' {
                        // is it known argument or unknown?
                        match classify_hyphen_token(&next) {
                            HyphClass::Known => return ctx.missing_value(def),
                            HyphClass::UnknownLong(name) => {
                                let shown = format!("--{}", name);
                                let suggestion = did_you_mean_long(&name);
                                if let Some(sug) = suggestion {
                                    let mut used: Vec<DefId> = Vec::new();
                                    for o in &occs { if !used.contains(&o.id) { used.push(o.id); } }
                                    if let Some(d) = def_by_long(&sug) { if !used.contains(&d.id) { used.push(d.id); } }
                                    let usage = ctx.usage_from_used(&used, has_files);
                                    return ctx.err_with_usage(format!("unexpected argument '{}' found\n\n  tip: a similar argument exists: '--{}'", shown, sug), usage);
                                } else {
                                    let usage = ctx.generic_usage();
                                    return ctx.err_with_usage(format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'", shown, shown, shown), usage);
                                }
                            }
                            HyphClass::UnknownShort(c) => {
                                let shown = format!("-{}", c);
                                let usage = ctx.generic_usage();
                                return ctx.err_with_usage(format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'", shown, shown, shown), usage);
                            }
                        }
                    }
                    value_os = next;
                    i += 2;
                }
                if seen.contains(&def.id) {
                    return ctx.multiple(def);
                }
                // empty disallow
                if is_empty_disallowed(def.id) && value_os.as_bytes().is_empty() {
                    return ctx.missing_value(def);
                }
                match validate_and_apply(&ctx, &mut params, def, &value_os) {
                    Ok(()) => { record!(def.id); }
                    Err(out) => return out,
                }
                continue;
            }
        } else if bytes.len() >= 2 && bytes[0] == b'-' {
            // short cluster
            let token = arg_os.to_string_lossy().to_string();
            let chars: Vec<char> = token[1..].chars().collect();
            let mut pos: usize = 0;
            let mut consumed_next = false;
            while pos < chars.len() {
                let c = chars[pos];
                let def_opt = def_by_short(c);
                if def_opt.is_none() {
                    let shown = format!("-{}", c);
                    let usage = ctx.generic_usage();
                    return ctx.err_with_usage(format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'", shown, shown, shown), usage);
                }
                let def = def_opt.unwrap();
                match def.id {
                    DefId::Help => {
                        print!("{}", help_short(&bin));
                        return CliOutcome::Exit(0);
                    }
                    DefId::Version => {
                        println!("caesiumclt 1.3.0");
                        return CliOutcome::Exit(0);
                    }
                    _ => {}
                }
                if def.value_name.is_none() {
                    if seen.contains(&def.id) {
                        return ctx.multiple(def);
                    }
                    record!(def.id);
                    apply_flag(&mut params, def.id);
                    pos += 1;
                    continue;
                } else {
                    // value-taking short
                    let rest: String = chars[pos + 1..].iter().collect();
                    let value_os: OsString;
                    if !rest.is_empty() {
                        if let Some(stripped) = rest.strip_prefix('=') {
                            value_os = OsString::from(stripped.to_string());
                        } else {
                            value_os = OsString::from(rest);
                        }
                        i += 1;
                    } else {
                        if i + 1 >= argv.len() {
                            return ctx.missing_value(def);
                        }
                        let next = argv[i + 1].clone();
                        let nb = next.as_bytes();
                        if nb == b"--" {
                            return ctx.missing_value(def);
                        }
                        if nb.len() > 1 && nb[0] == b'-' {
                            match classify_hyphen_token(&next) {
                                HyphClass::Known => return ctx.missing_value(def),
                                HyphClass::UnknownLong(name) => {
                                    let shown = format!("--{}", name);
                                    let suggestion = did_you_mean_long(&name);
                                    if let Some(sug) = suggestion {
                                        let mut used: Vec<DefId> = Vec::new();
                                        for o in &occs { if !used.contains(&o.id) { used.push(o.id); } }
                                        if let Some(d) = def_by_long(&sug) { if !used.contains(&d.id) { used.push(d.id); } }
                                        let usage = ctx.usage_from_used(&used, has_files);
                                        return ctx.err_with_usage(format!("unexpected argument '{}' found\n\n  tip: a similar argument exists: '--{}'", shown, sug), usage);
                                    } else {
                                        let usage = ctx.generic_usage();
                                        return ctx.err_with_usage(format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'", shown, shown, shown), usage);
                                    }
                                }
                                HyphClass::UnknownShort(ch) => {
                                    let shown = format!("-{}", ch);
                                    let usage = ctx.generic_usage();
                                    return ctx.err_with_usage(format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'", shown, shown, shown), usage);
                                }
                            }
                        }
                        value_os = next;
                        consumed_next = true;
                        i += 2;
                    }
                    if seen.contains(&def.id) {
                        return ctx.multiple(def);
                    }
                    if is_empty_disallowed(def.id) && value_os.as_bytes().is_empty() {
                        return ctx.missing_value(def);
                    }
                    match validate_and_apply(&ctx, &mut params, def, &value_os) {
                        Ok(()) => { record!(def.id); }
                        Err(out) => return out,
                    }
                    pos = chars.len();
                    break;
                }
            }
            if !consumed_next && chars.len() > 0 {
                // i already incremented in attached-value case; for pure flag clusters need advance
                // Determine if we advanced: if last processed was flag cluster, i not yet advanced
                // We can track: if a value was taken from rest, i+=1 done. If flags only, need i+=1.
                // Use heuristic: if no value option processed in this token, advance.
                // We set consumed_next only for next-arg case. Add flag:
                // Simplest: if token processing ended via flags, i+=1; but attached case already did.
                // We know attached case sets pos==len and breaks with i incremented.
                // Flag-only loop also ends with pos==len, but i not incremented. Distinguish by checking if any short def in token takes value.
                let has_value_short = chars.iter().any(|ch| def_by_short(*ch).map(|d| d.value_name.is_some()).unwrap_or(false));
                if !has_value_short {
                    i += 1;
                }
            }
            continue;
        } else {
            // positional file
            match arg_os.to_str() {
                None => return ctx.invalid_utf8(),
                Some(s) => {
                    if !seen.contains(&DefId::Files) { seen.push(DefId::Files); }
                    has_files = true;
                    params.files.push(s.to_string());
                }
            }
            i += 1;
            continue;
        }
    }

    // after parsing: conflicts
    // distinct presented option ids in parse order (excluding Files, Help, Version)
    let mut distinct: Vec<DefId> = Vec::new();
    for o in &occs {
        if o.id != DefId::Files && !distinct.contains(&o.id) { distinct.push(o.id); }
    }
    for id in &distinct {
        let mut others: Vec<DefId> = Vec::new();
        for other in &distinct {
            if other == id { continue; }
            if conflicts_with(*id, *other) && !others.contains(other) {
                others.push(*other);
            }
        }
        if !others.is_empty() {
            let def = def_by_id(*id);
            let msg = if others.len() == 1 {
                format!("the argument '{}' cannot be used with '{}'", def.render, def_by_id(others[0]).render)
            } else {
                let mut m = format!("the argument '{}' cannot be used with:", def.render);
                for o in &others { m.push_str(&format!("\n  {}", def_by_id(*o).render)); }
                m
            };
            // usage: all distinct except others
            let mut used: Vec<DefId> = Vec::new();
            for d in &distinct { if !others.contains(d) { used.push(*d); } }
            if has_files { used.push(DefId::Files); }
            let usage = ctx.usage_from_used(&used, has_files);
            return ctx.err_with_usage(msg, usage);
        }
    }
    // missing required
    let has_comp = distinct.iter().any(|d| group_of(*d) == Some(1));
    let has_out = distinct.iter().any(|d| group_of(*d) == Some(2));
    if !has_comp || !has_out {
        let mut msg = "the following required arguments were not provided:".to_string();
        if !has_comp { msg.push_str(&format!("\n  {}", group_render(1))); }
        if !has_out { msg.push_str(&format!("\n  {}", group_render(2))); }
        let mut used = distinct.clone();
        if has_files { used.push(DefId::Files); }
        let usage = ctx.usage_from_used(&used, has_files);
        return ctx.err_with_usage(msg, usage);
    }
    // quiet overrides verbose handling: quiet already applied as flag; verbosity effective computed in main
    CliOutcome::Run(Box::new(params))
}

enum HyphClass {
    Known,
    UnknownLong(String),
    UnknownShort(char),
}

fn classify_hyphen_token(os: &OsString) -> HyphClass {
    let s = os.to_string_lossy().to_string();
    if s.starts_with("--") {
        let body = &s[2..];
        let name = body.split('=').next().unwrap_or("");
        if def_by_long(name).is_some() { HyphClass::Known } else { HyphClass::UnknownLong(name.to_string()) }
    } else {
        // short: first char
        let c = s[1..].chars().next().unwrap_or('\0');
        if def_by_short(c).is_some() { HyphClass::Known } else { HyphClass::UnknownShort(c) }
    }
}

fn apply_flag(params: &mut Params, id: DefId) {
    match id {
        DefId::Lossless => params.lossless = true,
        DefId::NoUpscale => params.no_upscale = true,
        DefId::SameFolder => params.same_folder_as_input = true,
        DefId::JpegBaseline => params.jpeg_baseline = true,
        DefId::Zopfli => params.zopfli = true,
        DefId::Exif => params.exif = true,
        DefId::KeepDates => params.keep_dates = true,
        DefId::StripIcc => params.strip_icc = true,
        DefId::Recursive => params.recursive = true,
        DefId::KeepStructure => params.keep_structure = true,
        DefId::DryRun => params.dry_run = true,
        DefId::Quiet => params.quiet = true,
        _ => {}
    }
}

fn validate_and_apply(ctx: &Ctx, params: &mut Params, def: &Def, value_os: &OsString) -> Result<(), CliOutcome> {
    let id = def.id;
    // enums and output accept non-utf8 (lossy / raw)
    match id {
        DefId::Format | DefId::Chroma | DefId::Overwrite => {
            let s = value_os.to_string_lossy().to_string();
            let vals = def.possible.unwrap();
            if !vals.contains(&s.as_str()) {
                return Err(ctx.invalid_value(def, &s, None));
            }
            match id {
                DefId::Format => {
                    params.format = match s.as_str() {
                        "jpeg" => OutFormat::Jpeg, "png" => OutFormat::Png, "gif" => OutFormat::Gif,
                        "webp" => OutFormat::Webp, "tiff" => OutFormat::Tiff, _ => OutFormat::Original,
                    };
                }
                DefId::Chroma => {
                    params.jpeg_chroma = match s.as_str() {
                        "4:4:4" => Chroma::Y444, "4:2:2" => Chroma::Y422, "4:2:0" => Chroma::Y420,
                        "4:1:1" => Chroma::Y411, _ => Chroma::Auto,
                    };
                }
                DefId::Overwrite => {
                    params.overwrite = match s.as_str() {
                        "never" => Overwrite::Never, "bigger" => Overwrite::Bigger, _ => Overwrite::All,
                    };
                }
                _ => {}
            }
            return Ok(());
        }
        DefId::Output => {
            params.output = Some(PathBuf::from(value_os.clone()));
            return Ok(());
        }
        _ => {}
    }
    let s = match value_os.to_str() {
        None => return Err(ctx.invalid_utf8()),
        Some(v) => v.to_string(),
    };
    match id {
        DefId::Quality => match parse_quality(&s) {
            Ok(v) => params.quality = Some(v),
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::MaxSize => match parse_max_size(&s) {
            Ok(v) => params.max_size = Some(v),
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::Width => match parse_u32_clap(&s) {
            Ok(v) => params.width = Some(v),
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::Height => match parse_u32_clap(&s) {
            Ok(v) => params.height = Some(v),
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::LongEdge => match parse_u32_clap(&s) {
            Ok(v) => params.long_edge = Some(v),
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::ShortEdge => match parse_u32_clap(&s) {
            Ok(v) => params.short_edge = Some(v),
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::PngOpt => match parse_png_opt(&s) {
            Ok(v) => params.png_opt_level = v,
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::Threads => match parse_u32_clap(&s) {
            Ok(v) => params.threads = v,
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::Verbose => match parse_verbose(&s) {
            Ok(v) => params.verbose = v,
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        DefId::Suffix => params.suffix = Some(s),
        DefId::MinSavings => match parse_min_savings(&s) {
            Ok(v) => params.min_savings = Some(v),
            Err(r) => return Err(ctx.invalid_value(def, &s, Some(r))),
        },
        _ => {}
    }
    Ok(())
}
