pub fn format_size(size: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = 1024 * 1024;
    const GIB: u64 = 1024 * 1024 * 1024;
    const TIB: u64 = 1024 * 1024 * 1024 * 1024;
    if size < KIB {
        format!("{} B", size)
    } else if size < MIB {
        format!("{:.1} KiB", size as f64 / KIB as f64)
    } else if size < GIB {
        format!("{:.1} MiB", size as f64 / MIB as f64)
    } else if size < TIB {
        format!("{:.1} GiB", size as f64 / GIB as f64)
    } else {
        format!("{:.1} TiB", size as f64 / TIB as f64)
    }
}

fn format_diff(input: u64, output: u64) -> String {
    if output > input {
        let diff = output - input;
        let pct = if input == 0 { f64::NAN } else { (output as f64 - input as f64) / input as f64 * 100.0 };
        format!("+{} | +{:.2}%", format_size(diff), pct)
    } else {
        let diff = input - output;
        let pct = if input == 0 { f64::NAN } else { (input as f64 - output as f64) / input as f64 * 100.0 };
        format!("-{} | -{:.2}%", format_size(diff), pct)
    }
}

fn size_line(input: u64, output: u64) -> String {
    format!("{} -> {} [{}]", format_size(input), format_size(output), format_diff(input, output))
}

fn detect_format_from_header(header: &[u8]) -> Option<codec::Format> {
    if header.len() >= 4 && header[0] == 0x89 && header[1] == b'P' && header[2] == b'N' && header[3] == b'G' {
        return Some(codec::Format::Png);
    }
    if header.len() >= 3 && header[0] == 0xFF && header[1] == 0xD8 && header[2] == 0xFF {
        return Some(codec::Format::Jpeg);
    }
    if header.len() >= 3 && &header[0..3] == b"GIF" {
        return Some(codec::Format::Gif);
    }
    if header.len() >= 12 && &header[8..12] == b"WEBP" {
        return Some(codec::Format::Webp);
    }
    None
}

fn is_image_file(path: &Path) -> bool {
    let mut f = match fs::File::open(path) { Ok(f) => f, Err(_) => return false };
    let mut buf = [0u8; 16];
    // read exactly 16 like original (files smaller than 16 excluded)
    let mut read = 0usize;
    while read < 16 {
        match f.read(&mut buf[read..16]) {
            Ok(0) => return false,
            Ok(n) => read += n,
            Err(_) => return false,
        }
    }
    detect_format_from_header(&buf).is_some()
}

fn scan_dir(dir: &Path, recursive: bool, out: &mut Vec<PathBuf>) {
    let entries = match fs::read_dir(dir) { Ok(e) => e, Err(_) => return };
    for entry in entries {
        let entry = match entry { Ok(e) => e, Err(_) => continue };
        let path = entry.path();
        let ft = match entry.file_type() { Ok(t) => t, Err(_) => continue };
        if ft.is_dir() {
            if recursive {
                scan_dir(&path, recursive, out);
            }
        } else if ft.is_file() {
            if is_image_file(&path) { out.push(path); }
        } else if ft.is_symlink() {
            // follow for files, do not descend into linked dirs
            if path.is_file() && is_image_file(&path) { out.push(path); }
        }
    }
}

fn scan_files(params: &Params) -> Vec<PathBuf> {
    let mut out: Vec<PathBuf> = Vec::new();
    for file_str in &params.files {
        let path = PathBuf::from(file_str);
        if path.is_dir() {
            scan_dir(&path, params.recursive, &mut out);
        } else if path.is_file() {
            if is_image_file(&path) { out.push(path); }
        }
    }
    out
}

fn compute_base_path(files: &[PathBuf]) -> Option<PathBuf> {
    if files.is_empty() { return None; }
    let mut parents: Vec<PathBuf> = Vec::new();
    for f in files {
        let abs = std::path::absolute(f).unwrap_or_else(|_| f.clone());
        match abs.parent() {
            Some(p) => parents.push(p.to_path_buf()),
            None => return None,
        }
    }
    let mut common: Vec<std::path::Component> = parents[0].components().collect();
    for p in &parents[1..] {
        let comps: Vec<std::path::Component> = p.components().collect();
        let mut new_common = Vec::new();
        for (a, b) in common.iter().zip(comps.iter()) {
            if a == b { new_common.push(*a); } else { break; }
        }
        common = new_common;
        if common.is_empty() { break; }
    }
    let mut result = PathBuf::new();
    for c in common { result.push(c.as_os_str()); }
    Some(result)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Status { Success, Skipped, Error }

#[derive(Clone)]
struct FileResult {
    input: PathBuf,
    output: PathBuf,
    input_size: u64,
    output_size: u64,
    status: Status,
    message: Option<String>,
}

fn new_filename(input: &Path, params: &Params, target_ext: Option<&str>) -> String {
    let stem = input.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let suffix = params.suffix.clone().unwrap_or_default();
    match target_ext {
        Some(ext) => format!("{}{}.{}", stem, suffix, ext),
        None => {
            // original extension
            match input.extension() {
                Some(e) => {
                    let es = e.to_string_lossy().to_string();
                    if es.is_empty() {
                        format!("{}{}", stem, suffix)
                    } else {
                        format!("{}{}.{}", stem, suffix, es)
                    }
                }
                None => format!("{}{}", stem, suffix),
            }
        }
    }
}

fn target_format_and_ext(params: &Params, detected: codec::Format) -> (codec::Format, Option<String>) {
    match params.format {
