        OutFormat::Png => (codec::Format::Png, Some("png".to_string())),
        OutFormat::Gif => (codec::Format::Gif, Some("gif".to_string())),
        OutFormat::Webp => (codec::Format::Webp, Some("webp".to_string())),
        OutFormat::Tiff => (codec::Format::Tiff, Some("tiff".to_string())),
