        }
    } else if !params.dry_run && output_dir_for_file.as_os_str().is_empty() {
        // create_dir_all("") in Rust is Ok; nothing to do
    }
    // If output_dir exists as file etc, creation skipped; final write will fail later.
    let output_path = if output_dir_for_file.as_os_str().is_empty() {
        PathBuf::from(&filename)
    } else {
        output_dir_for_file.join(&filename)
    };

    // overwrite never
    if matches!(params.overwrite, Overwrite::Never) && output_path.exists() {
        return FileResult {
            input: input.to_path_buf(), output: output_path, input_size, output_size: input_size,
            status: Status::Skipped, message: Some("File already exists, skipped due overwrite policy".to_string()),
        };
    }
    if params.dry_run {
        return FileResult {
            input: input.to_path_buf(), output: output_path, input_size, output_size: input_size,
            status: Status::Success, message: None,
        };
    }

    // read input bytes
    let data = match fs::read(input) {
        Ok(d) => d,
        Err(e) => {
            return mk_error(output_path.clone(), Some(format!("Error compressing file: {} [10400]", e)));
        }
    };
    let detected = match codec::detect_format(&data) {
        Some(f) => f,
        None => {
            return mk_error(output_path.clone(), Some("Error compressing file: The image format could not be determined [10403]".to_string()));
        }
    };
    let (target_format, _) = target_format_and_ext(params, detected);

    // Special zero-size GIF panic emulation
    if target_format == codec::Format::Gif && detected == codec::Format::Gif && params.format == OutFormat::Original {
        if let Some((w, h)) = codec::gif_logical_size(&data) {
            if w == 0 || h == 0 {
                codec::panic_gif_zero();
            }
        }
    }

    let is_conversion = params.format != OutFormat::Original;
    let is_max = params.max_size.is_some();

    let compressed: Result<Vec<u8>, codec::CompError> = if is_max && is_conversion {
        // max-size conversion: errors are silent (no message)
        match codec::compress_to_max_size(&data, detected, target_format, params.max_size.unwrap(), params) {
            Ok(v) => Ok(v),
            Err(_) => {
                return FileResult {
                    input: input.to_path_buf(), output: output_path, input_size, output_size: 0,
                    status: Status::Error, message: None,
                };
            }
        }
    } else if is_conversion {
        if target_format == detected {
            return mk_error(output_path.clone(), Some("Error compressing file: Cannot convert to the same format [10407]".to_string()));
        }
        codec::convert(&data, detected, target_format, params)
    } else {
        codec::compress(&data, detected, params)
    };

    let compressed_data = match compressed {
        Ok(v) => v,
        Err(e) => {
            let msg = if is_conversion && !is_max {
                match e.convert_message {
                    Some(m) => Some(m),
                    None => Some(format!("Error compressing file: {} [{}]", e.message, e.code)),
                }
            } else {
                Some(format!("Error compressing file: {} [{}]", e.message, e.code))
            };
            // GIF double code special case embedded in message/code handling
            let final_msg = if e.extra_code.is_some() {
                Some(format!("Error compressing file: {} [{}] [{}]", e.message, e.code, e.extra_code.unwrap()))
            } else { msg };
            return mk_error(output_path.clone(), final_msg);
        }
    };
    let compressed_size = compressed_data.len() as u64;

    // min savings
    if let Some(min) = &params.min_savings {
        let saved: u64 = input_size.saturating_sub(compressed_size);
        let insufficient = match min {
            MinSavings::Percentage(p) => {
                let pct = if input_size == 0 { 0.0 } else { saved as f64 / input_size as f64 * 100.0 };
                if pct <= *p {
                    Some(format!("Insufficient savings: {:.2}% < {:.2}%, skipped", pct, p))
                } else { None }
            }
            MinSavings::Absolute(bytes) => {
                if saved <= *bytes {
                    Some(format!("Insufficient savings: {} < {}, skipped", format_size(saved), format_size(*bytes)))
                } else { None }
            }
        };
        if let Some(m) = insufficient {
            return FileResult {
                input: input.to_path_buf(), output: output_path, input_size, output_size: input_size,
                status: Status::Skipped, message: Some(m),
            };
        }
    }
    // bigger
    if matches!(params.overwrite, Overwrite::Bigger) && output_path.exists() {
        let existing = fs::metadata(&output_path).map(|m| m.len()).unwrap_or(0);
        if existing <= compressed_size {
            return FileResult {
                input: input.to_path_buf(), output: output_path, input_size, output_size: input_size,
                status: Status::Skipped, message: Some("File already exists, skipped due overwrite policy".to_string()),
            };
        }
    }
    // write
    let write_result = (|| -> std::io::Result<()> {
        let mut f = fs::File::create(&output_path)?;
        use std::io::Write;
        f.write_all(&compressed_data)?;
        Ok(())
    })();
    if write_result.is_err() {
        return mk_error(output_path.clone(), Some("Error creating output file".to_string()));
    }
    if params.keep_dates {
        if let Ok(meta) = fs::metadata(input) {
            if let Ok(mtime) = meta.modified() {
                if let Ok(f) = fs::OpenOptions::new().write(true).open(&output_path) {
                    let _ = f.set_modified(mtime);
                }
            }
        }
    }
    FileResult {
        input: input.to_path_buf(), output: output_path, input_size, output_size: compressed_size,
        status: Status::Success, message: None,
    }
}

fn run(params: &Params) -> i32 {
    let verbose = verbosity(params);
    if params.files.is_empty() {
        eprintln!("No files to compress");
        return 0;
    }
    let files = scan_files(params);
    let base = match compute_base_path(&files) {
        Some(b) => b,
        None => {
            eprintln!("Unable to compute the base path for the files.");
            return 255;
        }
    };
    // process (parallel if threads allow)
    let cpu = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1);
    let effective_threads = if params.threads == 0 { cpu } else { std::cmp::min(params.threads as usize, cpu).max(1) };
    let results: Vec<FileResult> = if effective_threads <= 1 || files.len() <= 1 {
        files.iter().map(|f| process_file(f, params, &base)).collect()
    } else {
        let files_arc = Arc::new(files.clone());
        let params_arc = Arc::new(params.clone());
        let base_arc = Arc::new(base.clone());
        let index = Arc::new(Mutex::new(0usize));
        let (tx, rx) = std::sync::mpsc::channel::<(usize, FileResult)>();
        let mut handles = Vec::new();
        let workers = effective_threads.min(files_arc.len());
        for _ in 0..workers {
            let files_c = files_arc.clone();
            let params_c = params_arc.clone();
            let base_c = base_arc.clone();
            let index_c = index.clone();
            let tx_c = tx.clone();
            handles.push(std::thread::spawn(move || loop {
                let idx = {
                    let mut guard = index_c.lock().unwrap();
                    let cur = *guard;
                    if cur >= files_c.len() { break; }
                    *guard += 1;
                    cur
                };
                let result = process_file(&files_c[idx], &params_c, &base_c);
                let _ = tx_c.send((idx, result));
            }));
        }
        drop(tx);
        let mut collected: Vec<Option<FileResult>> = vec![None; files_arc.len()];
        for (idx, res) in rx {
            collected[idx] = Some(res);
        }
        for h in handles { let _ = h.join(); }
        collected.into_iter().map(|o| o.unwrap()).collect()
    };

    let mut success = 0u64;
    let mut skipped = 0u64;
    let mut errors = 0u64;
    let mut total_in: u64 = 0;
    let mut total_out: u64 = 0;
    for r in &results {
        total_in = total_in.wrapping_add(r.input_size);
        total_out = total_out.wrapping_add(r.output_size);
        match r.status {
            Status::Success => success += 1,
            Status::Skipped => skipped += 1,
            Status::Error => errors += 1,
        }
        let show = match verbose {
            3 => true,
            2 => r.status != Status::Success,
            _ => false,
        };
        if show {
            let label = match r.status {
                Status::Success => "Success",
                Status::Skipped => "Skipped",
                Status::Error => "Error",
            };
            println!("[{}] {} -> {}", label, r.input.display(), r.output.display());
            println!("{}", size_line(r.input_size, r.output_size));
            if let Some(m) = &r.message {
                println!("{}", m);
            }
            println!();
        }
    }
    if verbose >= 1 {
        let total = results.len();
        println!("Compressed {} files ({} success, {} skipped, {} errors)", total, success, skipped, errors);
        println!("{}", size_line(total_in, total_out));
    }
    0
}
RS"}

