            Ok(p) => p,
            Err(_) => return mk_error(PathBuf::new(), Some("Error setting up output path".to_string())),
        };
        let rel = match abs_parent.strip_prefix(base) {
            Ok(r) => r.to_path_buf(),
            Err(_) => return mk_error(PathBuf::new(), Some("Error setting up output path".to_string())),
        };
        keep_relative = Some(rel);
    }
