        return FileResult {
            input: input.to_path_buf(), output: output_path, input_size, output_size: input_size,
            status: Status::Skipped, message: Some("File already exists, skipped due overwrite policy".to_string()),
        };
    }
    if params.dry_run {
        return FileResult {
            input: input.to_path_buf(), output: output_path, input_size, output_size: input_size,
            status: Status::Success, message: None,
        };
    }

