    } else {
        let files_arc = Arc::new(files.clone());
        let params_arc = Arc::new(params.clone());
        let base_arc = Arc::new(base.clone());
        let index = Arc::new(Mutex::new(0usize));
        let (tx, rx) = std::sync::mpsc::channel::<(usize, FileResult)>();
        let mut handles = Vec::new();
        let workers = effective_threads.min(files_arc.len());
        for _ in 0..workers {
            let files_c = files_arc.clone();
            let params_c = params_arc.clone();
            let base_c = base_arc.clone();
            let index_c = index.clone();
            let tx_c = tx.clone();
