        }
        for h in handles { let _ = h.join(); }
        collected.into_iter().map(|o| o.unwrap()).collect()
    };

    let mut success = 0u64;
    let mut skipped = 0u64;
    let mut errors = 0u64;
    let mut total_in: u64 = 0;
    let mut total_out: u64 = 0;
    for r in &results {
        total_in = total_in.wrapping_add(r.input_size);
        total_out = total_out.wrapping_add(r.output_size);
        match r.status {
            Status::Success => success += 1,
            Status::Skipped => skipped += 1,
            Status::Error => errors += 1,
        }
        let show = match verbose {
            3 => true,
            2 => r.status != Status::Success,
            _ => false,
        };
        if show {
            let label = match r.status {
                Status::Success => "Success",
                Status::Skipped => "Skipped",
                Status::Error => "Error",
            };
            println!("[{}] {} -> {}", label, r.input.display(), r.output.display());
            println!("{}", size_line(r.input_size, r.output_size));
            if let Some(m) = &r.message {
                println!("{}", m);
            }
            println!();
        }
    }
    if verbose >= 1 {
        let total = results.len();
        println!("Compressed {} files ({} success, {} skipped, {} errors)", total, success, skipped, errors);
        println!("{}", size_line(total_in, total_out));
    }
    0
}
