fn detect_format_from_header(header: &[u8]) -> Option<codec::Format> {
    if header.len() >= 4 && header[0] == 0x89 && header[1] == b'P' && header[2] == b'N' && header[3] == b'G' {
        return Some(codec::Format::Png);
    }
    if header.len() >= 3 && header[0] == 0xFF && header[1] == 0xD8 && header[2] == 0xFF {
        return Some(codec::Format::Jpeg);
    }
    if header.len() >= 3 && &header[0..3] == b"GIF" {
        return Some(codec::Format::Gif);
    }
    if header.len() >= 12 && &header[8..12] == b"WEBP" {
        return Some(codec::Format::Webp);
    }
    None
}

fn is_image_file(path: &Path) -> bool {
    let mut f = match fs::File::open(path) { Ok(f) => f, Err(_) => return false };
    let mut buf = [0u8; 16];
    // read exactly 16 like original (files smaller than 16 excluded)
    let mut read = 0usize;
    while read < 16 {
        match f.read(&mut buf[read..16]) {
            Ok(0) => return false,
            Ok(n) => read += n,
            Err(_) => return false,
        }
    }
    detect_format_from_header(&buf).is_some()
