#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <setjmp.h>

/* Minimal libjpeg (JPEG_LIB_VERSION 80, libjpeg-turbo) declarations.
   Structs are represented as opaque byte buffers with verified offsets. */

extern void *jpeg_std_error(void *err);
extern void jpeg_CreateCompress(void *cinfo, int version, size_t structsize);
extern void jpeg_CreateDecompress(void *cinfo, int version, size_t structsize);
extern void jpeg_destroy_compress(void *cinfo);
extern void jpeg_destroy_decompress(void *cinfo);
extern void jpeg_mem_dest(void *cinfo, unsigned char **outbuffer, unsigned long *outlen);
extern void jpeg_mem_src(void *cinfo, const unsigned char *inbuffer, unsigned long inlen);
extern void jpeg_set_defaults(void *cinfo);
extern void jpeg_set_quality(void *cinfo, int quality, int force_baseline);
extern void jpeg_simple_progression(void *cinfo);
extern void jpeg_start_compress(void *cinfo, int write_all_tables);
extern unsigned int jpeg_write_scanlines(void *cinfo, unsigned char **scanlines, unsigned int num_lines);
extern void jpeg_finish_compress(void *cinfo);
extern int jpeg_read_header(void *cinfo, int require_image);
extern int jpeg_start_decompress(void *cinfo);
extern unsigned int jpeg_read_scanlines(void *cinfo, unsigned char **scanlines, unsigned int num_lines);
extern int jpeg_finish_decompress(void *cinfo);
extern void *jpeg_read_coefficients(void *cinfo);
extern void jpeg_write_coefficients(void *cinfo, void *coef_arrays);
extern void jpeg_copy_critical_parameters(void *dst, void *src);
extern void jpeg_save_markers(void *cinfo, int marker_code, unsigned int max_length);

/* jpeg_error_mgr layout: 5 function pointers, then msg_code at offset 40. */
struct err_mgr {
    void *fn[5];
    int msg_code;
    unsigned char rest[512];
    jmp_buf jb;
    char message[256];
};

static void my_error_exit(void *cinfo) {
    struct err_mgr *err = *(struct err_mgr **)cinfo;
    /* format_message is fn[3]: void (*)(cinfo, buffer) */
    typedef void (*fmt_fn)(void *, char *);
    if (err->fn[3]) {
        ((fmt_fn)err->fn[3])(cinfo, err->message);
    } else {
        err->message[0] = 0;
    }
    longjmp(err->jb, 1);
}
static void my_output_message(void *cinfo) {
    (void)cinfo;
}
static struct err_mgr *make_err(void) {
    struct err_mgr *err = (struct err_mgr *)calloc(1, sizeof(struct err_mgr));
    jpeg_std_error(err);
    err->fn[0] = (void *)my_error_exit;
    err->fn[2] = (void *)my_output_message;
    return err;
}

#define CINFO_SIZE 4096

int cj_decode(const unsigned char *in, unsigned long inlen,
              unsigned char **out, int *out_w, int *out_h,
              int *err_code, char *err_msg, unsigned long err_cap) {
    struct err_mgr *err = make_err();
    unsigned char *cinfo = (unsigned char *)calloc(1, CINFO_SIZE);
    *(void **)cinfo = err;
    if (setjmp(err->jb)) {
        if (err_code) *err_code = err->msg_code;
        if (err_msg && err_cap) { strncpy(err_msg, err->message, err_cap - 1); err_msg[err_cap - 1] = 0; }
        jpeg_destroy_decompress(cinfo);
        free(cinfo); free(err);
        return 1;
    }
    jpeg_CreateDecompress(cinfo, 80, 656);
    jpeg_mem_src(cinfo, in, inlen);
    jpeg_read_header(cinfo, 1);
    int w = *(int *)(cinfo + 48);
    int h = *(int *)(cinfo + 52);
    /* out_color_space at 64: 2 = JCS_RGB */
    *(int *)(cinfo + 64) = 2;
    jpeg_start_decompress(cinfo);
    int ow = *(int *)(cinfo + 136);
    int oh = *(int *)(cinfo + 140);
    if (ow > 0) w = ow;
    if (oh > 0) h = oh;
    if (w <= 0 || h <= 0) {
        if (err_code) *err_code = 0;
        if (err_msg && err_cap) { strncpy(err_msg, "empty output image", err_cap - 1); err_msg[err_cap-1]=0; }
        jpeg_destroy_decompress(cinfo);
        free(cinfo); free(err);
        return 2;
    }
    unsigned char *pixels = (unsigned char *)malloc((size_t)w * (size_t)h * 3u);
    unsigned char *row = pixels;
    size_t stride = (size_t)w * 3u;
    int rows = 0;
    while (rows < h) {
        unsigned char *rp = row;
        unsigned int n = jpeg_read_scanlines(cinfo, &rp, 1);
        if (n == 0) break;
        row += stride;
        rows++;
    }
    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    free(cinfo); free(err);
    *out = pixels; *out_w = w; *out_h = h;
    return 0;
}

/* sampling: 0=4:4:4, 1=4:2:2, 2=4:2:0, 3=4:1:1; components 3 (RGB) or 1 (gray input stored as rgb with all equal? caller passes components) */
int cj_encode(const unsigned char *rgb, int w, int h, int components,
              int quality, int progressive, int sampling,
              unsigned char **out, unsigned long *out_len,
              int *err_code, char *err_msg, unsigned long err_cap) {
    struct err_mgr *err = make_err();
    unsigned char *cinfo = (unsigned char *)calloc(1, CINFO_SIZE);
    *(void **)cinfo = err;
    unsigned char *obuf = NULL;
    unsigned long olen = 0;
    if (setjmp(err->jb)) {
        if (err_code) *err_code = err->msg_code;
        if (err_msg && err_cap) { strncpy(err_msg, err->message, err_cap - 1); err_msg[err_cap - 1] = 0; }
        jpeg_destroy_compress(cinfo);
        if (obuf) free(obuf);
        free(cinfo); free(err);
        return 1;
    }
    jpeg_CreateCompress(cinfo, 80, 584);
    jpeg_mem_dest(cinfo, &obuf, &olen);
    *(uint32_t *)(cinfo + 48) = (uint32_t)w;
    *(uint32_t *)(cinfo + 52) = (uint32_t)h;
    *(int *)(cinfo + 56) = components;
    *(int *)(cinfo + 60) = (components == 1) ? 1 : 2; /* JCS_GRAYSCALE=1, JCS_RGB=2 */
    *(double *)(cinfo + 64) = 1.0;
    jpeg_set_defaults(cinfo);
    /* sampling via comp_info at 104, stride 96, h at +8, v at +12 */
    if (components == 3) {
        unsigned char *comp = *(unsigned char **)(cinfo + 104);
        int hs[3] = {1,1,1}, vs[3] = {1,1,1};
        if (sampling == 1) { hs[0]=2; vs[0]=1; }
        else if (sampling == 2) { hs[0]=2; vs[0]=2; }
        else if (sampling == 3) { hs[0]=4; vs[0]=1; }
        for (int i = 0; i < 3; i++) {
            *(int *)(comp + i * 96 + 8) = hs[i];
            *(int *)(comp + i * 96 + 12) = vs[i];
        }
    }
    jpeg_set_quality(cinfo, quality, 1);
    *(int *)(cinfo + 296) = 1; /* optimize_coding */
    if (progressive) jpeg_simple_progression(cinfo);
    jpeg_start_compress(cinfo, 1);
    size_t stride = (size_t)w * (size_t)components;
    for (int y = 0; y < h; y++) {
        unsigned char *rp = (unsigned char *)rgb + (size_t)y * stride;
        jpeg_write_scanlines(cinfo, &rp, 1);
    }
    jpeg_finish_compress(cinfo);
    jpeg_destroy_compress(cinfo);
    free(cinfo); free(err);
    *out = obuf; *out_len = olen;
    return 0;
}

int cj_transcode(const unsigned char *in, unsigned long inlen, int baseline,
                 unsigned char **out, unsigned long *out_len,
                 int *err_code, char *err_msg, unsigned long err_cap) {
    struct err_mgr *errd = make_err();
    struct err_mgr *errc = make_err();
    unsigned char *dinfo = (unsigned char *)calloc(1, CINFO_SIZE);
    unsigned char *cinfo = (unsigned char *)calloc(1, CINFO_SIZE);
    *(void **)dinfo = errd;
    *(void **)cinfo = errc;
    unsigned char *obuf = NULL;
    unsigned long olen = 0;
    if (setjmp(errd->jb)) {
        if (err_code) *err_code = errd->msg_code;
        if (err_msg && err_cap) { strncpy(err_msg, errd->message, err_cap - 1); err_msg[err_cap - 1] = 0; }
        jpeg_destroy_decompress(dinfo);
        free(dinfo); free(cinfo); free(errd); free(errc);
        return 1;
    }
    if (setjmp(errc->jb)) {
        if (err_code) *err_code = errc->msg_code;
        if (err_msg && err_cap) { strncpy(err_msg, errc->message, err_cap - 1); err_msg[err_cap - 1] = 0; }
        jpeg_destroy_decompress(dinfo);
        jpeg_destroy_compress(cinfo);
        if (obuf) free(obuf);
        free(dinfo); free(cinfo); free(errd); free(errc);
        return 1;
    }
    jpeg_CreateDecompress(dinfo, 80, 656);
    jpeg_mem_src(dinfo, in, inlen);
    jpeg_read_header(dinfo, 1);
    void *coefs = jpeg_read_coefficients(dinfo);
    jpeg_CreateCompress(cinfo, 80, 584);
    jpeg_mem_dest(cinfo, &obuf, &olen);
    jpeg_copy_critical_parameters(dinfo, cinfo);
    if (baseline) {
        /* Force sequential (single-scan) output: clear scan scripts at 272/280 */
        *(int *)(cinfo + 272) = 0;
        *(void **)(cinfo + 280) = NULL;
        *(int *)(cinfo + 296) = 0; /* optimize off */
    }
    jpeg_write_coefficients(cinfo, coefs);
    jpeg_finish_compress(cinfo);
    jpeg_destroy_decompress(dinfo);
    jpeg_destroy_compress(cinfo);
    free(dinfo); free(cinfo); free(errd); free(errc);
    *out = obuf; *out_len = olen;
    return 0;
}
