        png_chunk(&mut out, b"IHDR", &ihdr);
        // PLTE
        let mut plte = Vec::new();
        for c in palette { plte.extend_from_slice(&c[0..3]); }
        png_chunk(&mut out, b"PLTE", &plte);
        // tRNS if any alpha <255
        if palette.iter().any(|c| c[3] < 255) {
            let alphas: Vec<u8> = palette.iter().map(|c| c[3]).collect();
            // trim trailing 255
            let mut end = alphas.len();
            while end > 0 && alphas[end - 1] == 255 { end -= 1; }
            if end > 0 { png_chunk(&mut out, b"tRNS", &alphas[..end]); }
        }
        for (t, d) in extra_chunks { let mut tt = [0u8;4]; tt.copy_from_slice(&t[0..4]); png_chunk(&mut out, &tt, d); }
        // IDAT from indices
        let indices = &use_palette.as_ref().unwrap().1;
        let mut raw = Vec::with_capacity((img.w as usize + 1) * img.h as usize);
        for y in 0..img.h as usize {
            raw.push(0);
            raw.extend_from_slice(&indices[y * img.w as usize..(y + 1) * img.w as usize]);
        }
        let comp = zlib_compress(&raw, level);
        png_chunk(&mut out, b"IDAT", &comp);
    } else {
        let has_alpha = img.has_alpha();
        let gray = img.gray_hint && img.rgba.chunks_exact(4).all(|p| p[0] == p[1] && p[1] == p[2]);
        let (ct, channels): (u8, usize) = if gray && !has_alpha { (0, 1) } else if gray && has_alpha { (4, 2) } else if has_alpha { (6, 4) } else { (2, 3) };
        ihdr.push(8); ihdr.push(ct); ihdr.push(0); ihdr.push(0); ihdr.push(0);
        png_chunk(&mut out, b"IHDR", &ihdr);
        for (t, d) in extra_chunks { let mut tt = [0u8;4]; tt.copy_from_slice(&t[0..4]); png_chunk(&mut out, &tt, d); }
        // build raw with filter selection per row
        let mut raw = Vec::new();
        let mut prev: Vec<u8> = vec![0u8; img.w as usize * channels];
        for y in 0..img.h as usize {
            let mut row = Vec::with_capacity(img.w as usize * channels);
            for x in 0..img.w as usize {
                let p = &img.rgba[(y * img.w as usize + x) * 4..(y * img.w as usize + x) * 4 + 4];
                match ct {
                    0 => row.push(p[0]),
                    4 => { row.push(p[0]); row.push(p[3]); },
                    2 => row.extend_from_slice(&p[0..3]),
                    _ => row.extend_from_slice(p),
                }
            }
            // choose filter minimizing sum of absolute signed byte values
            let mut best_filter = 0u8; let mut best_data = row.clone(); let mut best_score = i64::MAX;
            for filt in 0..5u8 {
                let mut data = vec![0u8; row.len()];
                for i in 0..row.len() {
                    let a = if i >= channels { row[i - channels] as i32 } else { 0 };
                    let b = prev[i] as i32;
                    let c = if i >= channels { prev[i - channels] as i32 } else { 0 };
                    let pred = match filt { 0 => 0, 1 => a, 2 => b, 3 => (a + b) / 2, _ => paeth(a, b, c) };
                    data[i] = (row[i] as i32 - pred) as u8;
                }
                let score: i64 = data.iter().map(|&v| { let s = v as i8; (s as i64).abs() }).sum();
                if score < best_score { best_score = score; best_filter = filt; best_data = data; }
            }
            raw.push(best_filter);
            raw.extend_from_slice(&best_data);
            prev = row;
        }
        let comp = zlib_compress(&raw, level);
        png_chunk(&mut out, b"IDAT", &comp);
    }
    png_chunk(&mut out, b"IEND", &[]);
    out
}
RS"}

