use crate::cli::{Chroma, OutFormat, Params};
use std::collections::HashMap;
use std::ffi::c_void;
use std::path::Path;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Format { Jpeg, Png, Gif, Webp, Tiff }

#[derive(Clone, Debug)]
pub struct CompError {
    pub message: String,
    pub code: u32,
    pub extra_code: Option<u32>,
    pub convert_message: Option<String>,
}
impl CompError {
    pub fn new(message: &str, code: u32) -> Self {
        CompError { message: message.to_string(), code, extra_code: None, convert_message: None }
    }
    pub fn with_extra(message: &str, code: u32, extra: u32) -> Self {
        CompError { message: message.to_string(), code, extra_code: Some(extra), convert_message: None }
    }
}

pub fn detect_format(data: &[u8]) -> Option<Format> {
    if data.len() >= 4 && data[0] == 0x89 && data[1] == b'P' && data[2] == b'N' && data[3] == b'G' {
        return Some(Format::Png);
    }
    if data.len() >= 3 && data[0] == 0xFF && data[1] == 0xD8 && data[2] == 0xFF {
        return Some(Format::Jpeg);
    }
    if data.len() >= 3 && &data[0..3] == b"GIF" {
        return Some(Format::Gif);
    }
    if data.len() >= 12 && &data[8..12] == b"WEBP" {
        return Some(Format::Webp);
    }
    None
}

pub fn gif_logical_size(data: &[u8]) -> Option<(u16, u16)> {
    if data.len() >= 10 && &data[0..3] == b"GIF" {
        Some((u16::from_le_bytes([data[6], data[7]]), u16::from_le_bytes([data[8], data[9]])))
    } else { None }
}

