}

// ---------- FFI: zlib ----------
#[link(name = "z")]
extern "C" {
    fn compressBound(sourceLen: u64) -> u64;
    fn compress2(dest: *mut u8, destLen: *mut u64, source: *const u8, sourceLen: u64, level: i32) -> i32;
    fn uncompress(dest: *mut u8, destLen: *mut u64, source: *const u8, sourceLen: u64) -> i32;
}
pub fn zlib_compress(data: &[u8], level: i32) -> Vec<u8> {
    unsafe {
        let bound = compressBound(data.len() as u64);
        let mut out = vec![0u8; bound as usize];
        let mut out_len = bound;
        let rc = compress2(out.as_mut_ptr(), &mut out_len, data.as_ptr(), data.len() as u64, level);
        if rc != 0 { // fall back to stored-like by using level 0 retry
            let mut out2 = vec![0u8; bound as usize];
            let mut l2 = bound;
            let _ = compress2(out2.as_mut_ptr(), &mut l2, data.as_ptr(), data.len() as u64, 0);
            out2.truncate(l2 as usize);
            return out2;
        }
        out.truncate(out_len as usize);
        out
    }
}
pub fn zlib_uncompress(data: &[u8], expected: usize) -> Option<Vec<u8>> {
    unsafe {
        let mut out = vec![0u8; expected];
        let mut out_len = expected as u64;
        let rc = uncompress(out.as_mut_ptr(), &mut out_len, data.as_ptr(), data.len() as u64);
        if rc != 0 { return None; }
        out.truncate(out_len as usize);
        Some(out)
    }
}

// ---------- FFI: jpeg helper ----------
extern "C" {
    fn cj_decode(input: *const u8, inlen: u64, out: *mut *mut u8, out_w: *mut i32, out_h: *mut i32, err_code: *mut i32, err_msg: *mut u8, err_cap: u64) -> i32;
    fn cj_encode(rgb: *const u8, w: i32, h: i32, components: i32, quality: i32, progressive: i32, sampling: i32, out: *mut *mut u8, out_len: *mut u64, err_code: *mut i32, err_msg: *mut u8, err_cap: u64) -> i32;
    fn cj_transcode(input: *const u8, inlen: u64, baseline: i32, out: *mut *mut u8, out_len: *mut u64, err_code: *mut i32, err_msg: *mut u8, err_cap: u64) -> i32;
    fn free(ptr: *mut c_void);
}

#[derive(Clone, Debug)]
pub struct Image {
    pub w: u32,
    pub h: u32,
    pub rgba: Vec<u8>, // RGBA8, len w*h*4
    pub gray_hint: bool,
}
impl Image {
    pub fn new(w: u32, h: u32, rgba: Vec<u8>) -> Image { Image { w, h, rgba, gray_hint: false } }
    pub fn is_opaque(&self) -> bool { self.rgba.iter().skip(3).step_by(4).all(|&a| a == 255) }
    pub fn has_alpha(&self) -> bool { !self.is_opaque() }
}

fn sampling_code(c: Chroma) -> i32 {
    match c { Chroma::Y444 => 0, Chroma::Y422 => 1, Chroma::Y420 | Chroma::Auto => 2, Chroma::Y411 => 3 }
}

pub fn decode_jpeg(data: &[u8]) -> Result<Image, CompError> {
    unsafe {
        let mut out: *mut u8 = std::ptr::null_mut();
        let mut w: i32 = 0; let mut h: i32 = 0; let mut code: i32 = 0;
        let mut msg = vec![0u8; 512];
        let rc = cj_decode(data.as_ptr(), data.len() as u64, &mut out, &mut w, &mut h, &mut code, msg.as_mut_ptr(), msg.len() as u64);
        if rc != 0 {
            let e = CompError::new(&format!("Internal JPEG error: {}", code), 20104);
            return Err(e);
        }
        let pixels = std::slice::from_raw_parts(out, (w * h * 3) as usize).to_vec();
        free(out as *mut c_void);
        let mut rgba = Vec::with_capacity((w * h * 4) as usize);
        for px in pixels.chunks_exact(3) { rgba.extend_from_slice(&[px[0], px[1], px[2], 255]); }
        Ok(Image::new(w as u32, h as u32, rgba))
    }
}
fn encode_jpeg(img: &Image, quality: u32, params: &Params) -> Result<Vec<u8>, CompError> {
    // flatten to RGB
    let mut rgb = Vec::with_capacity((img.w * img.h * 3) as usize);
    for px in img.rgba.chunks_exact(4) { rgb.extend_from_slice(&px[0..3]); }
    unsafe {
        let mut out: *mut u8 = std::ptr::null_mut(); let mut out_len: u64 = 0; let mut code: i32 = 0;
        let mut msg = vec![0u8; 512];
        let progressive = if params.jpeg_baseline { 0 } else { 1 };
        let rc = cj_encode(rgb.as_ptr(), img.w as i32, img.h as i32, 3, quality as i32, progressive, sampling_code(params.jpeg_chroma), &mut out, &mut out_len, &mut code, msg.as_mut_ptr(), msg.len() as u64);
        if rc != 0 {
            return Err(CompError::new(&format!("Internal JPEG error: {}", code), 20104));
        }
        let bytes = std::slice::from_raw_parts(out, out_len as usize).to_vec();
        free(out as *mut c_void);
        Ok(bytes)
    }
}
fn transcode_jpeg(data: &[u8], params: &Params) -> Result<Vec<u8>, CompError> {
    unsafe {
        let mut out: *mut u8 = std::ptr::null_mut(); let mut out_len: u64 = 0; let mut code: i32 = 0;
        let mut msg = vec![0u8; 512];
        let rc = cj_transcode(data.as_ptr(), data.len() as u64, if params.jpeg_baseline { 1 } else { 0 }, &mut out, &mut out_len, &mut code, msg.as_mut_ptr(), msg.len() as u64);
        if rc != 0 {
            return Err(CompError::new(&format!("Internal JPEG error: {}", code), 20104));
        }
        let bytes = std::slice::from_raw_parts(out, out_len as usize).to_vec();
        free(out as *mut c_void);
        Ok(bytes)
    }
}

// ---------- PNG ----------
fn crc32(bytes: &[u8]) -> u32 {
    // Use zlib crc? implement table
    static mut TABLE: [u32; 256] = [0; 256];
    static ONCE: std::sync::Once = std::sync::Once::new();
    unsafe {
        ONCE.call_once(|| {
            for i in 0..256u32 {
                let mut c = i;
                for _ in 0..8 { c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 }; }
                TABLE[i as usize] = c;
            }
        });
        let mut crc: u32 = 0xFFFFFFFF;
        for &b in bytes { crc = TABLE[((crc ^ b as u32) & 0xFF) as usize] ^ (crc >> 8); }
        crc ^ 0xFFFFFFFF
    }
}
fn png_chunk(out: &mut Vec<u8>, typ: &[u8; 4], data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    out.extend_from_slice(typ);
    out.extend_from_slice(data);
    let mut crc_data = Vec::with_capacity(4 + data.len());
    crc_data.extend_from_slice(typ); crc_data.extend_from_slice(data);
    out.extend_from_slice(&crc32(&crc_data).to_be_bytes());
}

#[derive(Clone, Debug)]
struct PngInfo {
    w: u32, h: u32, bit_depth: u8, color_type: u8, interlace: u8,
    palette: Vec<[u8; 3]>,
    trns: Vec<u8>,
    raw_idat: Vec<u8>, // compressed stream (concatenated)
    chunks: Vec<(String, Vec<u8>)>, // all chunks in order (type, data)
}
fn parse_png(data: &[u8]) -> Result<PngInfo, CompError> {
    let err = |m: &str| CompError::new(m, 20204);
    if data.len() < 33 { return Err(err("PNG file is smaller than a PNG header")); }
    if &data[0..8] != b"\x89PNG\r\n\x1a\n" { return Err(err("the first bytes are not the correct PNG signature")); }
    // first chunk must be IHDR
    if data.len() < 16 || &data[12..16] != b"IHDR" { return Err(err("first chunk is not the header chunk")); }
    let mut pos = 8usize;
    let mut info: Option<PngInfo> = None;
    let mut idat: Vec<u8> = Vec::new();
    let mut chunks: Vec<(String, Vec<u8>)> = Vec::new();
    while pos + 8 <= data.len() {
        let len = u32::from_be_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]) as usize;
        let typ_bytes = [data[pos + 4], data[pos + 5], data[pos + 6], data[pos + 7]];
        let typ = String::from_utf8_lossy(&typ_bytes).to_string();
        if pos + 8 + len + 4 > data.len() {
            // chunk broken off
            if info.is_none() { return Err(err("first chunk is not the header chunk")); }
            // If this is IDAT or any after IHDR, mimic chunk broken
            return Err(err("chunk length too large, chunk broken off at end of file"));
        }
        let cdata = data[pos + 8..pos + 8 + len].to_vec();
        chunks.push((typ.clone(), cdata.clone()));
        match &typ_bytes {
            b"IHDR" => {
                if cdata.len() < 13 { return Err(err("PNG file is smaller than a PNG header")); }
                let w = u32::from_be_bytes([cdata[0], cdata[1], cdata[2], cdata[3]]);
                let h = u32::from_be_bytes([cdata[4], cdata[5], cdata[6], cdata[7]]);
                if w == 0 || h == 0 { return Err(err("zero width or height is invalid")); }
                info = Some(PngInfo { w, h, bit_depth: cdata[8], color_type: cdata[9], interlace: cdata[12], palette: Vec::new(), trns: Vec::new(), raw_idat: Vec::new(), chunks: Vec::new() });
            }
            b"PLTE" => {
                if let Some(ref mut inf) = info {
                    for c in cdata.chunks_exact(3) { inf.palette.push([c[0], c[1], c[2]]); }
                }
            }
            b"tRNS" => { if let Some(ref mut inf) = info { inf.trns = cdata.clone(); } }
            b"IDAT" => { idat.extend_from_slice(&cdata); }
            b"IEND" => { break; }
            _ => {}
        }
        pos += 8 + len + 4;
    }
    let mut inf = match info { Some(i) => i, None => return Err(err("first chunk is not the header chunk")) };
    if idat.is_empty() {
        // inflate of nothing -> jumped past memory
        return Err(err("jumped past memory while inflating"));
    }
    inf.raw_idat = idat;
    inf.chunks = chunks;
    Ok(inf)
}

fn png_channels(ct: u8) -> usize { match ct { 0 => 1, 2 => 3, 3 => 1, 4 => 2, 6 => 4, _ => 0 } }

fn png_raw_size(info: &PngInfo) -> Option<usize> {
    let channels = png_channels(info.color_type);
    if channels == 0 { return None; }
    let bpp_bits = channels * info.bit_depth as usize;
    // For palette/gray sub-byte, bits per pixel = bit_depth
    let bits_per_pixel = if info.color_type == 3 || (info.color_type == 0 && info.bit_depth < 8) { info.bit_depth as usize } else { bpp_bits };
    let passes: Vec<(u32, u32)> = if info.interlace == 1 {
        let specs = [(0, 0, 8, 8), (4, 0, 8, 8), (0, 4, 4, 8), (2, 0, 4, 4), (0, 2, 2, 4), (1, 0, 2, 2), (0, 1, 1, 2)];
        specs.iter().map(|&(x0, y0, xs, ys)| {
            if info.w <= x0 || info.h <= y0 { (0, 0) } else { ((info.w - x0 + xs - 1) / xs, (info.h - y0 + ys - 1) / ys) }
        }).collect()
    } else { vec![(info.w, info.h)] };
    let mut total = 0usize;
    for (pw, ph) in passes {
        if pw == 0 || ph == 0 { continue; }
        let row_bytes = (bits_per_pixel * pw as usize + 7) / 8;
        total += (row_bytes + 1) * ph as usize;
    }
    Some(total)
}

fn paeth(a: i32, b: i32, c: i32) -> i32 {
    let p = a + b - c;
    let pa = (p - a).abs(); let pb = (p - b).abs(); let pc = (p - c).abs();
    if pa <= pb && pa <= pc { a } else if pb <= pc { b } else { c }
}

pub fn decode_png(data: &[u8]) -> Result<Image, CompError> {
    let info = parse_png(data)?;
    let expected = png_raw_size(&info).ok_or_else(|| CompError::new("unsupported PNG color type", 20204))?;
    let raw = zlib_uncompress(&info.raw_idat, expected)
        .ok_or_else(|| CompError::new("the length of the END symbol 256 in the Huffman tree is 0", 20204))?;
    if raw.len() < expected {
        return Err(CompError::new("jumped past memory while inflating", 20204));
    }
    let channels = png_channels(info.color_type);
    let bits_per_pixel = if info.color_type == 3 || (info.color_type == 0 && info.bit_depth < 8) { info.bit_depth as usize } else { channels * info.bit_depth as usize };
    let bpp_bytes = ((bits_per_pixel + 7) / 8).max(1);
    let mut image = Image::new(info.w, info.h, vec![0u8; (info.w * info.h * 4) as usize]);
    // helper to set pixel
    let passes: Vec<(u32, u32, u32, u32, u32, u32)> = if info.interlace == 1 {
        vec![(0,0,8,8),(4,0,8,8),(0,4,4,8),(2,0,4,4),(0,2,2,4),(1,0,2,2),(0,1,1,2)]
    } else { vec![(0,0,1,1)] };
    let mut offset = 0usize;
    for (x0, y0, xs, ys) in passes {
        if info.w <= x0 || info.h <= y0 { continue; }
        let pw = (info.w - x0 + xs - 1) / xs;
        let ph = (info.h - y0 + ys - 1) / ys;
        let row_bytes = (bits_per_pixel * pw as usize + 7) / 8;
        let mut prev_row = vec![0u8; row_bytes];
        for py in 0..ph {
            if offset + 1 + row_bytes > raw.len() { return Err(CompError::new("jumped past memory while inflating", 20204)); }
            let filter = raw[offset]; offset += 1;
            let mut row = raw[offset..offset + row_bytes].to_vec(); offset += row_bytes;
            match filter {
                0 => {},
                1 => { for i in bpp_bytes..row.len() { row[i] = row[i].wrapping_add(row[i - bpp_bytes]); } },
                2 => { for i in 0..row.len() { row[i] = row[i].wrapping_add(prev_row[i]); } },
                3 => {
                    for i in 0..row.len() {
                        let left = if i >= bpp_bytes { row[i - bpp_bytes] as i32 } else { 0 };
                        let up = prev_row[i] as i32;
                        row[i] = row[i].wrapping_add(((left + up) / 2) as u8);
                    }
                },
                4 => {
                    for i in 0..row.len() {
                        let a = if i >= bpp_bytes { row[i - bpp_bytes] as i32 } else { 0 };
                        let b = prev_row[i] as i32;
                        let c = if i >= bpp_bytes { prev_row[i - bpp_bytes] as i32 } else { 0 };
                        row[i] = row[i].wrapping_add(paeth(a, b, c) as u8);
                    }
                },
                _ => return Err(CompError::new("invalid PNG filter", 20204)),
            }
            // unpack pixels for this pass row
            for px in 0..pw {
                let real_x = x0 + px * xs;
                let real_y = y0 + py * ys;
                let idx = ((real_y * info.w + real_x) * 4) as usize;
                // extract samples
                let (r, g, b, a) = extract_png_pixel(&row, px as usize, &info);
                image.rgba[idx] = r; image.rgba[idx + 1] = g; image.rgba[idx + 2] = b; image.rgba[idx + 3] = a;
            }
            prev_row = row;
        }
    }
    if info.color_type == 0 || info.color_type == 4 { image.gray_hint = true; }
    Ok(image)
}

fn extract_png_pixel(row: &[u8], px: usize, info: &PngInfo) -> (u8, u8, u8, u8) {
    let bd = info.bit_depth;
    match info.color_type {
        3 => {
            let idx_val = extract_sample(row, px, bd);
            let pal = info.palette.get(idx_val).copied().unwrap_or([0, 0, 0]);
            let alpha = info.trns.get(idx_val).copied().unwrap_or(255);
            (pal[0], pal[1], pal[2], alpha)
        }
        0 => {
            let v = extract_sample_scaled(row, px, bd, 0);
            (v, v, v, 255)
        }
        4 => {
            // two samples per pixel
            let v = extract_sample_scaled_offset(row, px, bd, 0);
            let a = extract_sample_scaled_offset(row, px, bd, 1);
            (v, v, v, a)
        }
        2 => {
            let r = extract_sample_scaled_offset(row, px, bd, 0);
            let g = extract_sample_scaled_offset(row, px, bd, 1);
            let b = extract_sample_scaled_offset(row, px, bd, 2);
            (r, g, b, 255)
        }
        6 => {
            let r = extract_sample_scaled_offset(row, px, bd, 0);
            let g = extract_sample_scaled_offset(row, px, bd, 1);
            let b = extract_sample_scaled_offset(row, px, bd, 2);
            let a = extract_sample_scaled_offset(row, px, bd, 3);
            (r, g, b, a)
        }
        _ => (0, 0, 0, 255),
    }
}
fn extract_sample(row: &[u8], px: usize, bit_depth: u8) -> usize {
    match bit_depth {
        8 => row.get(px).copied().unwrap_or(0) as usize,
        16 => { let o = px * 2; row.get(o).copied().unwrap_or(0) as usize }, // high byte handled elsewhere; for palette not used
        1 | 2 | 4 => {
            let bits = bit_depth as usize;
