pub fn encode_png_rgba(img: &Image, use_palette: Option<(Vec<[u8; 4]>, Vec<u8>)>, level: i32, extra_chunks: &[(Vec<u8>, Vec<u8>)]) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
