    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&img.w.to_be_bytes());
    ihdr.extend_from_slice(&img.h.to_be_bytes());
    if let Some((palette, _indices)) = &use_palette {
        ihdr.push(8); ihdr.push(3); ihdr.push(0); ihdr.push(0); ihdr.push(0);
        png_chunk(&mut out, b"IHDR", &ihdr);
        // PLTE
        let mut plte = Vec::new();
        for c in palette { plte.extend_from_slice(&c[0..3]); }
        png_chunk(&mut out, b"PLTE", &plte);
