        let len = u32::from_be_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]) as usize;
        let typ_bytes = [data[pos + 4], data[pos + 5], data[pos + 6], data[pos + 7]];
        let typ = String::from_utf8_lossy(&typ_bytes).to_string();
        if pos + 8 + len + 4 > data.len() {
            // chunk broken off
            if info.is_none() { return Err(err("first chunk is not the header chunk")); }
            // If this is IDAT or any after IHDR, mimic chunk broken
            return Err(err("chunk length too large, chunk broken off at end of file"));
