    }
    let mut inf = match info { Some(i) => i, None => return Err(err("first chunk is not the header chunk")) };
    if idat.is_empty() {
        // inflate of nothing -> jumped past memory
        return Err(err("jumped past memory while inflating"));
    }
    inf.raw_idat = idat;
    inf.chunks = chunks;
    Ok(inf)
}

