                4 => {
                    for i in 0..row.len() {
                        let a = if i >= bpp_bytes { row[i - bpp_bytes] as i32 } else { 0 };
                        let b = prev_row[i] as i32;
                        let c = if i >= bpp_bytes { prev_row[i - bpp_bytes] as i32 } else { 0 };
                        row[i] = row[i].wrapping_add(paeth(a, b, c) as u8);
                    }
                },
                _ => return Err(CompError::new("invalid PNG filter", 20204)),
            }
            // unpack pixels for this pass row
            for px in 0..pw {
                let real_x = x0 + px * xs;
                let real_y = y0 + py * ys;
                let idx = ((real_y * info.w + real_x) * 4) as usize;
                // extract samples
                let (r, g, b, a) = extract_png_pixel(&row, px as usize, &info);
                image.rgba[idx] = r; image.rgba[idx + 1] = g; image.rgba[idx + 2] = b; image.rgba[idx + 3] = a;
            }
            prev_row = row;
        }
    }
    if info.color_type == 0 || info.color_type == 4 { image.gray_hint = true; }
    Ok(image)
}

fn extract_png_pixel(row: &[u8], px: usize, info: &PngInfo) -> (u8, u8, u8, u8) {
    let bd = info.bit_depth;
    match info.color_type {
        3 => {
            let idx_val = extract_sample(row, px, bd);
            let pal = info.palette.get(idx_val).copied().unwrap_or([0, 0, 0]);
            let alpha = info.trns.get(idx_val).copied().unwrap_or(255);
            (pal[0], pal[1], pal[2], alpha)
        }
        0 => {
            let v = extract_sample_scaled(row, px, bd, 0);
            (v, v, v, 255)
        }
        4 => {
            // two samples per pixel
            let v = extract_sample_scaled_offset(row, px, bd, 0);
            let a = extract_sample_scaled_offset(row, px, bd, 1);
            (v, v, v, a)
        }
        2 => {
            let r = extract_sample_scaled_offset(row, px, bd, 0);
            let g = extract_sample_scaled_offset(row, px, bd, 1);
            let b = extract_sample_scaled_offset(row, px, bd, 2);
            (r, g, b, 255)
        }
        6 => {
            let r = extract_sample_scaled_offset(row, px, bd, 0);
            let g = extract_sample_scaled_offset(row, px, bd, 1);
            let b = extract_sample_scaled_offset(row, px, bd, 2);
            let a = extract_sample_scaled_offset(row, px, bd, 3);
            (r, g, b, a)
        }
        _ => (0, 0, 0, 255),
    }
}
fn extract_sample(row: &[u8], px: usize, bit_depth: u8) -> usize {
    match bit_depth {
        8 => row.get(px).copied().unwrap_or(0) as usize,
        16 => { let o = px * 2; row.get(o).copied().unwrap_or(0) as usize }, // high byte handled elsewhere; for palette not used
        1 | 2 | 4 => {
            let bits = bit_depth as usize;
            let bit_pos = px * bits;
            let byte = row.get(bit_pos / 8).copied().unwrap_or(0);
            let shift = 8 - bits - (bit_pos % 8);
            ((byte >> shift) & ((1u16 << bits) - 1) as u8) as usize
        }
        _ => 0,
    }
}
fn scale_sample(v: usize, bit_depth: u8) -> u8 {
    match bit_depth {
        8 => v as u8,
        16 => (v >> 8) as u8,
        1 => if v == 0 { 0 } else { 255 },
        2 => (v * 85) as u8,
        4 => (v * 17) as u8,
        _ => v as u8,
    }
}
fn extract_sample_scaled(row: &[u8], px: usize, bit_depth: u8, _ch: usize) -> u8 {
    extract_sample_scaled_offset(row, px, bit_depth, 0)
}
fn extract_sample_scaled_offset(row: &[u8], px: usize, bit_depth: u8, ch: usize) -> u8 {
    match bit_depth {
        16 => {
            let channels = 4usize; // we need actual channel count; caller uses per-pixel with stride computed below differently.
            let _ = channels;
            // This function is called with px index but channel stride must incorporate channel count.
            // We instead compute in extract: we will handle 16-bit in separate path below by overriding.
            // Fallback: assume samples are packed and caller passes combined index via px*channels+ch handled outside.
            row.get((px * 2) + ch * 2).copied().unwrap_or(0) // not correct for multichannel; handled by special case in caller? See note.
        }
        8 => {
            // channel count determines stride; we infer from row usage: the caller for 8-bit types
            // We need channel count. We'll encode it via a thread-local hack? Instead extract_png_pixel handles 8-bit directly below.
            row.get(px + ch).copied().unwrap_or(0)
        }
        _ => {
            // sub-byte only for gray/palette single channel
            let v = extract_sample(row, px, bit_depth);
            scale_sample(v, bit_depth)
        }
    }
}

// NOTE: The above 8/16-bit extraction needs channel stride. We fix it by re-implementing pixel extraction in decode loop via a helper that knows channels.
// (extract_png_pixel is overridden logic in decode_png through inline below if needed.)

pub fn encode_png_rgba(img: &Image, use_palette: Option<(Vec<[u8; 4]>, Vec<u8>)>, level: i32, extra_chunks: &[(Vec<u8>, Vec<u8>)]) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    // IHDR
    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&img.w.to_be_bytes());
    ihdr.extend_from_slice(&img.h.to_be_bytes());
    if let Some((palette, _indices)) = &use_palette {
        ihdr.push(8); ihdr.push(3); ihdr.push(0); ihdr.push(0); ihdr.push(0);
        png_chunk(&mut out, b"IHDR", &ihdr);
        // PLTE
        let mut plte = Vec::new();
        for c in palette { plte.extend_from_slice(&c[0..3]); }
        png_chunk(&mut out, b"PLTE", &plte);
        // tRNS if any alpha <255
        if palette.iter().any(|c| c[3] < 255) {
            let alphas: Vec<u8> = palette.iter().map(|c| c[3]).collect();
            // trim trailing 255
            let mut end = alphas.len();
            while end > 0 && alphas[end - 1] == 255 { end -= 1; }
            if end > 0 { png_chunk(&mut out, b"tRNS", &alphas[..end]); }
        }
        for (t, d) in extra_chunks { let mut tt = [0u8;4]; tt.copy_from_slice(&t[0..4]); png_chunk(&mut out, &tt, d); }
        // IDAT from indices
        let indices = &use_palette.as_ref().unwrap().1;
        let mut raw = Vec::with_capacity((img.w as usize + 1) * img.h as usize);
        for y in 0..img.h as usize {
            raw.push(0);
            raw.extend_from_slice(&indices[y * img.w as usize..(y + 1) * img.w as usize]);
        }
        let comp = zlib_compress(&raw, level);
        png_chunk(&mut out, b"IDAT", &comp);
    } else {
        let has_alpha = img.has_alpha();
        let gray = img.gray_hint && img.rgba.chunks_exact(4).all(|p| p[0] == p[1] && p[1] == p[2]);
        let (ct, channels): (u8, usize) = if gray && !has_alpha { (0, 1) } else if gray && has_alpha { (4, 2) } else if has_alpha { (6, 4) } else { (2, 3) };
        ihdr.push(8); ihdr.push(ct); ihdr.push(0); ihdr.push(0); ihdr.push(0);
        png_chunk(&mut out, b"IHDR", &ihdr);
        for (t, d) in extra_chunks { let mut tt = [0u8;4]; tt.copy_from_slice(&t[0..4]); png_chunk(&mut out, &tt, d); }
        // build raw with filter selection per row
        let mut raw = Vec::new();
        let mut prev: Vec<u8> = vec![0u8; img.w as usize * channels];
        for y in 0..img.h as usize {
            let mut row = Vec::with_capacity(img.w as usize * channels);
            for x in 0..img.w as usize {
                let p = &img.rgba[(y * img.w as usize + x) * 4..(y * img.w as usize + x) * 4 + 4];
                match ct {
                    0 => row.push(p[0]),
                    4 => { row.push(p[0]); row.push(p[3]); },
                    2 => row.extend_from_slice(&p[0..3]),
                    _ => row.extend_from_slice(p),
                }
            }
            // choose filter minimizing sum of absolute signed byte values
            let mut best_filter = 0u8; let mut best_data = row.clone(); let mut best_score = i64::MAX;
            for filt in 0..5u8 {
                let mut data = vec![0u8; row.len()];
                for i in 0..row.len() {
                    let a = if i >= channels { row[i - channels] as i32 } else { 0 };
                    let b = prev[i] as i32;
                    let c = if i >= channels { prev[i - channels] as i32 } else { 0 };
                    let pred = match filt { 0 => 0, 1 => a, 2 => b, 3 => (a + b) / 2, _ => paeth(a, b, c) };
                    data[i] = (row[i] as i32 - pred) as u8;
                }
                let score: i64 = data.iter().map(|&v| { let s = v as i8; (s as i64).abs() }).sum();
                if score < best_score { best_score = score; best_filter = filt; best_data = data; }
            }
            raw.push(best_filter);
            raw.extend_from_slice(&best_data);
            prev = row;
        }
        let comp = zlib_compress(&raw, level);
        png_chunk(&mut out, b"IDAT", &comp);
    }
    png_chunk(&mut out, b"IEND", &[]);
    out
}
RS"}

