// ---------- WebP via dlopen ----------
struct WebpLib {
    _handle: *mut c_void,
    decode_rgba: unsafe extern "C" fn(*const u8, i32, *mut i32, *mut i32) -> *mut u8,
    encode_rgba: unsafe extern "C" fn(*const u8, i32, i32, i32, f32, *mut *mut u8) -> usize,
    encode_lossless_rgba: unsafe extern "C" fn(*const u8, i32, i32, i32, *mut *mut u8) -> usize,
    get_info: unsafe extern "C" fn(*const u8, usize, *mut i32, *mut i32) -> i32,
    free_fn: unsafe extern "C" fn(*mut c_void),
}
unsafe impl Send for WebpLib {}
unsafe impl Sync for WebpLib {}

extern "C" {
    fn dlopen(filename: *const i8, flag: i32) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const i8) -> *mut c_void;
}

fn webp_lib() -> Option<&'static WebpLib> {
    static LIB: std::sync::OnceLock<Option<WebpLib>> = std::sync::OnceLock::new();
    LIB.get_or_init(|| unsafe {
        let name = b"/lib/x86_64-linux-gnu/libwebp.so.7\0";
        let h = dlopen(name.as_ptr() as *const i8, 2 /* RTLD_NOW */);
        if h.is_null() { return None; }
        let sym = |n: &[u8]| { let p = dlsym(h, n.as_ptr() as *const i8); if p.is_null() { None } else { Some(p) } };
        Some(WebpLib {
            _handle: h,
            decode_rgba: std::mem::transmute(sym(b"WebPDecodeRGBA\0")?),
            encode_rgba: std::mem::transmute(sym(b"WebPEncodeRGBA\0")?),
            encode_lossless_rgba: std::mem::transmute(sym(b"WebPEncodeLosslessRGBA\0")?),
            get_info: std::mem::transmute(sym(b"WebPGetInfo\0")?),
            free_fn: std::mem::transmute(sym(b"WebPFree\0").unwrap_or(std::ptr::null_mut())),
        })
    }).as_ref()
}

pub fn decode_webp(data: &[u8]) -> Result<Image, CompError> {
    let lib = webp_lib().ok_or_else(|| CompError::new("null_decoder", 20304))?;
    unsafe {
        let mut w: i32 = 0; let mut h: i32 = 0;
        if (lib.get_info)(data.as_ptr(), data.len(), &mut w, &mut h) == 0 || w <= 0 || h <= 0 {
            return Err(CompError::new("null_decoder", 20304));
        }
        let p = (lib.decode_rgba)(data.as_ptr(), data.len() as i32, &mut w, &mut h);
        if p.is_null() { return Err(CompError::new("null_decoder", 20304)); }
        let bytes = std::slice::from_raw_parts(p, (w * h * 4) as usize).to_vec();
        if !(lib.free_fn as *const c_void).is_null() { (lib.free_fn)(p as *mut c_void); } else { free(p as *mut c_void); }
        Ok(Image::new(w as u32, h as u32, bytes))
    }
}
fn encode_webp(img: &Image, quality: u32, lossless: bool) -> Result<Vec<u8>, CompError> {
    let lib = webp_lib().ok_or_else(|| CompError::new("null_encoder", 20304))?;
    unsafe {
        let mut out: *mut u8 = std::ptr::null_mut();
        let stride = (img.w * 4) as i32;
        let n = if lossless {
            (lib.encode_lossless_rgba)(img.rgba.as_ptr(), img.w as i32, img.h as i32, stride, &mut out)
        } else {
            (lib.encode_rgba)(img.rgba.as_ptr(), img.w as i32, img.h as i32, stride, quality as f32, &mut out)
        };
        if n == 0 || out.is_null() { return Err(CompError::new("null_encoder", 20304)); }
        let bytes = std::slice::from_raw_parts(out, n).to_vec();
        if !(lib.free_fn as *const c_void).is_null() { (lib.free_fn)(out as *mut c_void); } else { free(out as *mut c_void); }
        Ok(bytes)
    }
}

// ---------- GIF ----------
#[derive(Clone, Debug)]
pub struct GifFrame {
    pub x: u16, pub y: u16, pub w: u16, pub h: u16,
    pub indices: Vec<u8>,
    pub palette: Vec<[u8; 3]>,
    pub delay_cs: u16,
    pub disposal: u8,
    pub trans_idx: Option<u8>,
}
#[derive(Clone, Debug)]
pub struct GifFile {
    pub w: u16, pub h: u16,
    pub frames: Vec<GifFrame>,
    pub loop_count: Option<u16>, // None = no loop ext, Some(0)=infinite
    pub composited: Vec<Image>, // one per frame (after drawing that frame)
}

struct GifParseErr { msg: String, code: u32, extra: Option<u32> }

fn gif_lzw_decode(min_code: u8, data: &[u8], expected: usize) -> Option<Vec<u8>> {
    if min_code < 2 || min_code > 8 { return None; }
    let clear = 1usize << min_code;
    let eoi = clear + 1;
    let mut table: Vec<Vec<u8>> = Vec::new();
    let reset_table = |table: &mut Vec<Vec<u8>>| {
        table.clear();
        for i in 0..clear { table.push(vec![i as u8]); }
        table.push(vec![]); table.push(vec![]);
    };
    reset_table(&mut table);
    let mut code_size = min_code + 1;
    let mut bit_pos = 0usize;
    let total_bits = data.len() * 8;
    let read_code = |bit_pos: &mut usize, cs: u8| -> Option<usize> {
        if *bit_pos + cs as usize > total_bits { return None; }
        let byte_i = *bit_pos / 8;
        let mut val: u32 = 0;
        let mut bits_read = 0usize;
        let mut bp = *bit_pos;
        while bits_read < cs as usize {
            let b = *data.get(bp / 8)? as u32;
            let bit = (b >> (bp % 8)) & 1;
            val |= bit << bits_read;
            bits_read += 1; bp += 1;
        }
        *bit_pos = bp;
        let _ = byte_i;
        Some(val as usize)
    };
    let mut out: Vec<u8> = Vec::with_capacity(expected);
    let mut prev: Option<Vec<u8>> = None;
    loop {
        let code = read_code(&mut bit_pos, code_size)?;
        if code == clear { reset_table(&mut table); code_size = min_code + 1; prev = None; continue; }
        if code == eoi { break; }
        let entry: Vec<u8> = if (code as usize) < table.len() {
            if table[code as usize].is_empty() { return None; }
            table[code as usize].clone()
        } else if code as usize == table.len() {
            if let Some(ref p) = prev {
                let mut e = p.clone(); e.push(p[0]); e
            } else { return None; }
        } else { return None; };
        out.extend_from_slice(&entry);
        if out.len() > expected { /* keep but trim at end */ }
        if let Some(ref p) = prev {
            let mut new_entry = p.clone(); new_entry.push(entry[0]);
            if table.len() < 4096 {
                table.push(new_entry);
                if table.len() == (1usize << code_size) && code_size < 12 { code_size += 1; }
            }
        }
        prev = Some(entry);
        if out.len() >= expected { break; }
    }
    if out.len() < expected { return None; }
    out.truncate(expected);
    Some(out)
}

fn read_subblocks(data: &[u8], pos: &mut usize) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    loop {
        if *pos >= data.len() { return None; }
        let sz = data[*pos] as usize; *pos += 1;
        if sz == 0 { break; }
        if *pos + sz > data.len() { return None; }
        out.extend_from_slice(&data[*pos..*pos + sz]);
        *pos += sz;
    }
    Some(out)
}

pub fn decode_gif(data: &[u8]) -> Result<GifFile, CompError> {
    let to_err = |e: GifParseErr| {
        if let Some(extra) = e.extra { CompError::with_extra(&e.msg, e.code, extra) } else { CompError::new(&e.msg, e.code) }
    };
    if data.len() < 13 {
        return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None }));
    }
    if &data[0..6] != b"GIF87a" && &data[0..6] != b"GIF89a" {
        return Err(to_err(GifParseErr { msg: "malformed GIF header".into(), code: 20404, extra: None }));
    }
    let w = u16::from_le_bytes([data[6], data[7]]);
    let h = u16::from_le_bytes([data[8], data[9]]);
    let packed = data[10];
    let mut pos = 13usize;
    let gct: Vec<[u8; 3]> = if packed & 0x80 != 0 {
        let size = 3 * (1usize << ((packed & 0x07) + 1));
        if pos + size > data.len() { return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None })); }
        let mut pal = Vec::new();
        for c in data[pos..pos + size].chunks_exact(3) { pal.push([c[0], c[1], c[2]]); }
        pos += size;
        pal
    } else { Vec::new() };
    let mut frames: Vec<GifFrame> = Vec::new();
    let mut loop_count: Option<u16> = None;
    let mut gce: Option<(u16, u8, Option<u8>)> = None; // delay, disposal, trans
    let mut composited: Vec<Image> = Vec::new();
    let cw = w as usize; let ch = h as usize;
    let mut canvas = vec![0u8; cw * ch * 4];
    let mut saved_canvas: Option<Vec<u8>> = None;
    let mut saw_image = false;
    loop {
        if pos >= data.len() {
            // EOF without trailer
            if frames.is_empty() {
                if saw_image {
                    return Err(to_err(GifParseErr { msg: "Found no usable frames to encode".into(), code: 20409, extra: Some(20411) }));
                }
                return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None }));
            } else {
                return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20406, extra: Some(20411) }));
            }
        }
        let block = data[pos]; pos += 1;
        match block {
            0x3B => break,
            0x21 => {
                if pos >= data.len() { return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None })); }
                let label = data[pos]; pos += 1;
                if label == 0xF9 {
                    // GCE: block size then data then terminator
                    if pos >= data.len() { return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None })); }
                    let sz = data[pos] as usize; pos += 1;
                    if pos + sz > data.len() { return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None })); }
                    let b = &data[pos..pos + sz]; pos += sz;
                    // terminator
                    if pos < data.len() && data[pos] == 0 { pos += 1; } else if let Some(_) = read_subblocks(data, &mut pos) {} else {}
                    if sz >= 4 {
                        let disposal = (b[0] >> 2) & 0x07;
                        let delay = u16::from_le_bytes([b[1], b[2]]);
                        let trans = if b[0] & 1 != 0 { Some(b[3]) } else { None };
                        gce = Some((delay, disposal, trans));
                    }
                } else if label == 0xFF {
                    // app extension
                    if pos >= data.len() { return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None })); }
                    let sz = data[pos] as usize; pos += 1;
                    if pos + sz > data.len() { return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None })); }
                    let app = data[pos..pos + sz].to_vec(); pos += sz;
                    let sub = read_subblocks(data, &mut pos);
                    if let (true, Some(subd)) = (app.starts_with(b"NETSCAPE2.0"), sub) {
                        if subd.len() >= 3 && subd[0] == 1 { loop_count = Some(u16::from_le_bytes([subd[1], subd[2]])); }
                    }
                } else {
                    if read_subblocks(data, &mut pos).is_none() {
                        return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20404, extra: None }));
                    }
                }
            }
            0x2C => {
                saw_image = true;
                if pos + 9 > data.len() {
                    if frames.is_empty() { return Err(to_err(GifParseErr { msg: "Found no usable frames to encode".into(), code: 20409, extra: Some(20411) })); }
                    return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20406, extra: Some(20411) }));
                }
                let x = u16::from_le_bytes([data[pos], data[pos + 1]]);
                let y = u16::from_le_bytes([data[pos + 2], data[pos + 3]]);
                let fw = u16::from_le_bytes([data[pos + 4], data[pos + 5]]);
                let fh = u16::from_le_bytes([data[pos + 6], data[pos + 7]]);
                let fpacked = data[pos + 8]; pos += 9;
                let mut palette = gct.clone();
                if fpacked & 0x80 != 0 {
                    let size = 3 * (1usize << ((fpacked & 0x07) + 1));
                    if pos + size > data.len() {
                        if frames.is_empty() { return Err(to_err(GifParseErr { msg: "Found no usable frames to encode".into(), code: 20409, extra: Some(20411) })); }
                        return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20406, extra: Some(20411) }));
                    }
                    palette.clear();
                    for c in data[pos..pos + size].chunks_exact(3) { palette.push([c[0], c[1], c[2]]); }
                    pos += size;
                }
                if pos >= data.len() {
                    if frames.is_empty() { return Err(to_err(GifParseErr { msg: "Found no usable frames to encode".into(), code: 20409, extra: Some(20411) })); }
                    return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20406, extra: Some(20411) }));
                }
                let min_code = data[pos]; pos += 1;
                let comp_data = match read_subblocks(data, &mut pos) {
                    Some(d) => d,
                    None => {
                        if frames.is_empty() { return Err(to_err(GifParseErr { msg: "Found no usable frames to encode".into(), code: 20409, extra: Some(20411) })); }
                        return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20406, extra: Some(20411) }));
                    }
                };
                let expected = fw as usize * fh as usize;
                let mut indices = match gif_lzw_decode(min_code, &comp_data, expected) {
                    Some(idx) => idx,
                    None => {
                        if frames.is_empty() { return Err(to_err(GifParseErr { msg: "Found no usable frames to encode".into(), code: 20409, extra: Some(20411) })); }
                        return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20406, extra: Some(20411) }));
                    }
                };
                if fpacked & 0x40 != 0 {
                    // deinterlace
                    let mut out_idx = vec![0u8; expected];
                    let order: Vec<usize> = {
                        let mut rows: Vec<usize> = Vec::new();
                        for (start, step) in [(0usize, 8usize), (4, 8), (2, 4), (1, 2)] {
                            let mut yy = start;
                            while yy < fh as usize { rows.push(yy); yy += step; }
                        }
                        rows
                    };
                    for (src_row, &dst_row) in order.iter().enumerate() {
                        let s = src_row * fw as usize; let d = dst_row * fw as usize;
                        if s + fw as usize <= indices.len() && d + fw as usize <= out_idx.len() {
                            out_idx[d..d + fw as usize].copy_from_slice(&indices[s..s + fw as usize]);
                        }
                    }
                    indices = out_idx;
                }
                let (delay, disposal, trans) = gce.take().unwrap_or((0, 0, None));
                let frame = GifFrame { x, y, w: fw, h: fh, indices: indices.clone(), palette: palette.clone(), delay_cs: delay, disposal, trans_idx: trans };
                // composite
                if disposal == 3 { saved_canvas = Some(canvas.clone()); }
                for fy in 0..fh as usize {
                    for fx in 0..fw as usize {
                        let idxv = indices[fy * fw as usize + fx];
                        if Some(idxv) == trans { continue; }
                        let cx = x as usize + fx; let cy = y as usize + fy;
                        if cx >= cw || cy >= ch { continue; }
                        let pal = palette.get(idxv as usize).copied().unwrap_or([0, 0, 0]);
                        let o = (cy * cw + cx) * 4;
                        canvas[o] = pal[0]; canvas[o + 1] = pal[1]; canvas[o + 2] = pal[2]; canvas[o + 3] = 255;
                    }
                }
                composited.push(Image::new(w as u32, h as u32, canvas.clone()));
                // apply disposal for next frame
                match disposal {
                    2 => {
                        for fy in 0..fh as usize {
                            for fx in 0..fw as usize {
                                let cx = x as usize + fx; let cy = y as usize + fy;
                                if cx >= cw || cy >= ch { continue; }
                                let o = (cy * cw + cx) * 4;
                                canvas[o] = 0; canvas[o + 1] = 0; canvas[o + 2] = 0; canvas[o + 3] = 0;
                            }
                        }
                    }
                    3 => { if let Some(saved) = saved_canvas.take() { canvas = saved; } }
                    _ => {}
                }
                frames.push(frame);
            }
            _ => {
                // unknown block
                if frames.is_empty() {
                    return Err(to_err(GifParseErr { msg: "malformed GIF header".into(), code: 20404, extra: None }));
                } else {
                    return Err(to_err(GifParseErr { msg: "unexpected end of file".into(), code: 20406, extra: Some(20411) }));
                }
            }
        }
    }
    if frames.is_empty() {
        return Err(to_err(GifParseErr { msg: "Found no usable frames to encode".into(), code: 20409, extra: Some(20411) }));
    }
    Ok(GifFile { w, h, frames, loop_count, composited })
}

fn gif_lzw_encode(min_code: u8, indices: &[u8]) -> Vec<u8> {
    let clear = 1usize << min_code;
    let eoi = clear + 1;
    let mut out_bits: Vec<u8> = Vec::new();
    let mut bit_buffer: u32 = 0; let mut bit_count: u32 = 0;
    let mut code_size = min_code + 1;
    let mut dict: HashMap<(u32, u8), u32> = HashMap::new();
    let mut next_code: u32;
    let reset = |dict: &mut HashMap<(u32, u8), u32>, cs: &mut u8, nc: &mut u32| {
        dict.clear(); *cs = min_code + 1; *nc = eoi as u32 + 1;
        let _ = cs;
    };
    // Use explicit code width tracking in emit closure emulation
    let mut emit = |code: u32, cs: u8, out_bits: &mut Vec<u8>, bb: &mut u32, bc: &mut u32| {
        *bb |= code << *bc;
        *bc += cs as u32;
        while *bc >= 8 {
            out_bits.push((*bb & 0xFF) as u8);
            *bb >>= 8; *bc -= 8;
        }
    };
    next_code = eoi as u32 + 1;
    emit(clear as u32, code_size, &mut out_bits, &mut bit_buffer, &mut bit_count);
    if indices.is_empty() {
        emit(eoi as u32, code_size, &mut out_bits, &mut bit_buffer, &mut bit_count);
    } else {
        let mut prefix: u32 = indices[0] as u32;
        for &k in &indices[1..] {
            if let Some(&code) = dict.get(&(prefix, k)) {
                prefix = code;
            } else {
                emit(prefix, code_size, &mut out_bits, &mut bit_buffer, &mut bit_count);
                if next_code < 4096 {
                    dict.insert((prefix, k), next_code);
                    next_code += 1;
                    if next_code - 1 == (1u32 << code_size) && code_size < 12 { code_size += 1; }
                } else {
                    emit(clear as u32, code_size, &mut out_bits, &mut bit_buffer, &mut bit_count);
                    reset(&mut dict, &mut code_size, &mut next_code);
                }
                prefix = k as u32;
            }
        }
        emit(prefix, code_size, &mut out_bits, &mut bit_buffer, &mut bit_count);
        emit(eoi as u32, code_size, &mut out_bits, &mut bit_buffer, &mut bit_count);
    }
    if bit_count > 0 { out_bits.push((bit_buffer & 0xFF) as u8); }
    out_bits
}

fn encode_gif_frames(w: u16, h: u16, frames: &[GifFrame], loop_count: Option<u16>) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"GIF89a");
    out.extend_from_slice(&w.to_le_bytes()); out.extend_from_slice(&h.to_le_bytes());
    out.push(0x80); out.push(0); out.push(0);
    out.extend_from_slice(&[0, 0, 0, 0, 0, 0]); // GCT 2 entries
    if let Some(loopn) = loop_count {
        out.push(0x21); out.push(0xFF); out.push(11);
        out.extend_from_slice(b"NETSCAPE2.0");
        out.push(3); out.push(1); out.extend_from_slice(&loopn.to_le_bytes()); out.push(0);
    }
    for fr in frames {
        // GCE
        out.push(0x21); out.push(0xF9); out.push(4);
        let mut packed = 0u8;
        packed |= ((fr.disposal & 0x07) << 2);
        if fr.trans_idx.is_some() { packed |= 1; }
        out.push(packed);
        out.extend_from_slice(&fr.delay_cs.to_le_bytes());
        out.push(fr.trans_idx.unwrap_or(0));
        out.push(0);
        // image descriptor
        out.push(0x2C);
        out.extend_from_slice(&fr.x.to_le_bytes()); out.extend_from_slice(&fr.y.to_le_bytes());
        out.extend_from_slice(&fr.w.to_le_bytes()); out.extend_from_slice(&fr.h.to_le_bytes());
        // palette size power of two
        let mut table_size: usize = 2;
        while table_size < fr.palette.len() { table_size *= 2; }
        let size_bits: u8 = match table_size { 2 => 0, 4 => 1, 8 => 2, 16 => 3, 32 => 4, 64 => 5, 128 => 6, _ => 7 };
        out.push(0x80 | size_bits);
        for i in 0..table_size {
            let c = fr.palette.get(i).copied().unwrap_or([0, 0, 0]);
            out.extend_from_slice(&c);
        }
        let min_code: u8 = std::cmp::max(2, size_bits + 1);
        out.push(min_code);
        let compressed = gif_lzw_encode(min_code, &fr.indices);
        for chunk in compressed.chunks(255) {
            out.push(chunk.len() as u8);
            out.extend_from_slice(chunk);
        }
        out.push(0);
    }
    out.push(0x3B);
    out
}
