// ---------- WebP via dlopen ----------
struct WebpLib {
    _handle: *mut c_void,
    decode_rgba: unsafe extern "C" fn(*const u8, i32, *mut i32, *mut i32) -> *mut u8,
    encode_rgba: unsafe extern "C" fn(*const u8, i32, i32, i32, f32, *mut *mut u8) -> usize,
    encode_lossless_rgba: unsafe extern "C" fn(*const u8, i32, i32, i32, *mut *mut u8) -> usize,
    get_info: unsafe extern "C" fn(*const u8, usize, *mut i32, *mut i32) -> i32,
    free_fn: unsafe extern "C" fn(*mut c_void),
}
unsafe impl Send for WebpLib {}
unsafe impl Sync for WebpLib {}

extern "C" {
    fn dlopen(filename: *const i8, flag: i32) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const i8) -> *mut c_void;
}

fn webp_lib() -> Option<&'static WebpLib> {
    static LIB: std::sync::OnceLock<Option<WebpLib>> = std::sync::OnceLock::new();
    LIB.get_or_init(|| unsafe {
        let name = b"/lib/x86_64-linux-gnu/libwebp.so.7\0";
        let h = dlopen(name.as_ptr() as *const i8, 2 /* RTLD_NOW */);
        if h.is_null() { return None; }
        let sym = |n: &[u8]| { let p = dlsym(h, n.as_ptr() as *const i8); if p.is_null() { None } else { Some(p) } };
        Some(WebpLib {
            _handle: h,
            decode_rgba: std::mem::transmute(sym(b"WebPDecodeRGBA\0")?),
            encode_rgba: std::mem::transmute(sym(b"WebPEncodeRGBA\0")?),
            encode_lossless_rgba: std::mem::transmute(sym(b"WebPEncodeLosslessRGBA\0")?),
            get_info: std::mem::transmute(sym(b"WebPGetInfo\0")?),
            free_fn: std::mem::transmute(sym(b"WebPFree\0").unwrap_or(std::ptr::null_mut())),
        })
    }).as_ref()
}

pub fn decode_webp(data: &[u8]) -> Result<Image, CompError> {
    let lib = webp_lib().ok_or_else(|| CompError::new("null_decoder", 20304))?;
    unsafe {
        let mut w: i32 = 0; let mut h: i32 = 0;
        if (lib.get_info)(data.as_ptr(), data.len(), &mut w, &mut h) == 0 || w <= 0 || h <= 0 {
            return Err(CompError::new("null_decoder", 20304));
        }
        let p = (lib.decode_rgba)(data.as_ptr(), data.len() as i32, &mut w, &mut h);
        if p.is_null() { return Err(CompError::new("null_decoder", 20304)); }
        let bytes = std::slice::from_raw_parts(p, (w * h * 4) as usize).to_vec();
        if !(lib.free_fn as *const c_void).is_null() { (lib.free_fn)(p as *mut c_void); } else { free(p as *mut c_void); }
        Ok(Image::new(w as u32, h as u32, bytes))
    }
}
fn encode_webp(img: &Image, quality: u32, lossless: bool) -> Result<Vec<u8>, CompError> {
    let lib = webp_lib().ok_or_else(|| CompError::new("null_encoder", 20304))?;
    unsafe {
        let mut out: *mut u8 = std::ptr::null_mut();
        let stride = (img.w * 4) as i32;
        let n = if lossless {
            (lib.encode_lossless_rgba)(img.rgba.as_ptr(), img.w as i32, img.h as i32, stride, &mut out)
        } else {
            (lib.encode_rgba)(img.rgba.as_ptr(), img.w as i32, img.h as i32, stride, quality as f32, &mut out)
        };
        if n == 0 || out.is_null() { return Err(CompError::new("null_encoder", 20304)); }
        let bytes = std::slice::from_raw_parts(out, n).to_vec();
        if !(lib.free_fn as *const c_void).is_null() { (lib.free_fn)(out as *mut c_void); } else { free(out as *mut c_void); }
        Ok(bytes)
    }
}

// ---------- GIF ----------
#[derive(Clone, Debug)]
pub struct GifFrame {
    pub x: u16, pub y: u16, pub w: u16, pub h: u16,
    pub indices: Vec<u8>,
    pub palette: Vec<[u8; 3]>,
    pub delay_cs: u16,
    pub disposal: u8,
    pub trans_idx: Option<u8>,
}
#[derive(Clone, Debug)]
pub struct GifFile {
    pub w: u16, pub h: u16,
    pub frames: Vec<GifFrame>,
    pub loop_count: Option<u16>, // None = no loop ext, Some(0)=infinite
    pub composited: Vec<Image>, // one per frame (after drawing that frame)
}

struct GifParseErr { msg: String, code: u32, extra: Option<u32> }

fn gif_lzw_decode(min_code: u8, data: &[u8], expected: usize) -> Option<Vec<u8>> {
    if min_code < 2 || min_code > 8 { return None; }
    let clear = 1usize << min_code;
    let eoi = clear + 1;
    let mut table: Vec<Vec<u8>> = Vec::new();
    let reset_table = |table: &mut Vec<Vec<u8>>| {
        table.clear();
        for i in 0..clear { table.push(vec![i as u8]); }
        table.push(vec![]); table.push(vec![]);
    };
    reset_table(&mut table);
    let mut code_size = min_code + 1;
    let mut bit_pos = 0usize;
    let total_bits = data.len() * 8;
    let read_code = |bit_pos: &mut usize, cs: u8| -> Option<usize> {
        if *bit_pos + cs as usize > total_bits { return None; }
        let byte_i = *bit_pos / 8;
        let mut val: u32 = 0;
        let mut bits_read = 0usize;
        let mut bp = *bit_pos;
        while bits_read < cs as usize {
            let b = *data.get(bp / 8)? as u32;
            let bit = (b >> (bp % 8)) & 1;
            val |= bit << bits_read;
            bits_read += 1; bp += 1;
        }
        *bit_pos = bp;
        let _ = byte_i;
        Some(val as usize)
    };
    let mut out: Vec<u8> = Vec::with_capacity(expected);
    let mut prev: Option<Vec<u8>> = None;
    loop {
        let code = read_code(&mut bit_pos, code_size)?;
        if code == clear { reset_table(&mut table); code_size = min_code + 1; prev = None; continue; }
        if code == eoi { break; }
        let entry: Vec<u8> = if (code as usize) < table.len() {
            if table[code as usize].is_empty() { return None; }
            table[code as usize].clone()
        } else if code as usize == table.len() {
            if let Some(ref p) = prev {
                let mut e = p.clone(); e.push(p[0]); e
            } else { return None; }
        } else { return None; };
        out.extend_from_slice(&entry);
        if out.len() > expected { /* keep but trim at end */ }
        if let Some(ref p) = prev {
            let mut new_entry = p.clone(); new_entry.push(entry[0]);
            if table.len() < 4096 {
                table.push(new_entry);
                if table.len() == (1usize << code_size) && code_size < 12 { code_size += 1; }
            }
        }
        prev = Some(entry);
        if out.len() >= expected { break; }
    }
    if out.len() < expected { return None; }
    out.truncate(expected);
    Some(out)
}

fn read_subblocks(data: &[u8], pos: &mut usize) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    loop {
        if *pos >= data.len() { return None; }
        let sz = data[*pos] as usize; *pos += 1;
        if sz == 0 { break; }
        if *pos + sz > data.len() { return None; }
        out.extend_from_slice(&data[*pos..*pos + sz]);
        *pos += sz;
    }
    Some(out)
}

pub fn decode_gif(data: &[u8]) -> Result<GifFile, CompError> {
    let to_err = |e: GifParseErr| {
