// EXIF orientation handling
pub fn exif_orientation(data: &[u8], fmt: Format) -> u16 {
    let tiff = extract_exif_tiff(data, fmt);
    if let Some(t) = tiff { return parse_tiff_orientation(&t); }
    1
}
fn parse_tiff_orientation(t: &[u8]) -> u16 {
    if t.len() < 8 { return 1; }
    let le = match &t[0..2] { b"II" => true, b"MM" => false, _ => return 1 };
    let read_u16 = |o: usize| -> Option<u16> {
        if o + 2 > t.len() { return None; }
        Some(if le { u16::from_le_bytes([t[o], t[o + 1]]) } else { u16::from_be_bytes([t[o], t[o + 1]]) })
    };
    let read_u32 = |o: usize| -> Option<u32> {
        if o + 4 > t.len() { return None; }
        Some(if le { u32::from_le_bytes([t[o], t[o + 1], t[o + 2], t[o + 3]]) } else { u32::from_be_bytes([t[o], t[o + 1], t[o + 2], t[o + 3]]) })
    };
    if read_u16(2) != Some(42) { return 1; }
    let ifd = match read_u32(4) { Some(v) => v as usize, None => return 1 };
    let count = match read_u16(ifd) { Some(v) => v as usize, None => return 1 };
    for i in 0..count {
        let e = ifd + 2 + i * 12;
        if e + 12 > t.len() { break; }
        if read_u16(e) == Some(274) {
            // value is in first two bytes of 4-byte value field (endian aware)
            if let Some(v) = read_u16(e + 8) { return v; }
        }
    }
    1
}
fn extract_exif_tiff(data: &[u8], fmt: Format) -> Option<Vec<u8>> {
    match fmt {
        Format::Jpeg => {
            let segs = parse_jpeg_segments(data);
            for (marker, payload) in segs {
                if marker == 0xE1 && payload.starts_with(b"Exif\x00\x00") { return Some(payload[6..].to_vec()); }
            }
            None
        }
        Format::Png => {
            if let Ok(info) = parse_png(data) {
                for (typ, cdata) in &info.chunks { if typ == "eXIf" { return Some(cdata.clone()); } }
            }
            None
        }
        Format::Webp => {
            let chunks = parse_webp_chunks(data);
            for (typ, payload) in chunks { if &typ == b"EXIF" { return Some(payload.to_vec()); } }
            None
        }
        _ => None,
    }
}
fn orientation_swaps(orient: u16) -> bool { matches!(orient, 5 | 6 | 7 | 8) }

/// Compute lib-level target size (stored coords) from width/height style params,
/// after swapping width/height if EXIF orientation swaps axes.
/// Returns None if no resize requested (or computed equals original).
fn compute_stored_target(w: u32, h: u32, req_w: Option<u32>, req_h: Option<u32>, swapped: bool, no_upscale: bool) -> Option<(u32, u32)> {
    let (mut rw, mut rh) = (req_w, req_h);
    if swapped { std::mem::swap(&mut rw, &mut rh); }
    // After swap, rw/rh are in stored terms. But the request was in oriented terms:
    // Actually swapping the request values converts oriented request to stored axis request.
    // However for single-dimension requests, the scale must be based on oriented dimension.
    // Equivalent stored-axis logic: if swapped and original req was width only, rw becomes None and rh = req (stored height request) -> correct below using stored dims.
    let (tw, th) = match (rw, rh) {
        (Some(x), Some(y)) => {
            if x == 0 && y == 0 { return None; }
            if x == 0 { let s = y as f64 / h as f64; (((w as f64 * s).round() as u32).max(1), y) }
            else if y == 0 { let s = x as f64 / w as f64; (x, ((h as f64 * s).round() as u32).max(1)) }
            else { (x, y) }
        }
        (Some(x), None) => {
            if x == 0 { return None; }
            let s = x as f64 / w as f64; (x, ((h as f64 * s).round() as u32).max(1))
        }
        (None, Some(y)) => {
            if y == 0 { return None; }
            let s = y as f64 / h as f64; (((w as f64 * s).round() as u32).max(1), y)
        }
        (None, None) => return None,
    };
    if tw == w && th == h { return None; }
    if no_upscale && (tw > w || th > h) { return None; }
    Some((tw, th))
}

/// Full resize planning for an image, given decoded format and original file bytes (for EXIF).
pub fn plan_resize(img: &Image, params: &Params, data: &[u8], fmt: Format) -> Option<(u32, u32)> {
    let orient = exif_orientation(data, fmt);
    let swapped = orientation_swaps(orient);
    if params.long_edge.is_some() || params.short_edge.is_some() {
        // CLT layer: dimensions depend on -e (keep_exif) for long/short translation
        let (dw, dh) = if params.exif && swapped { (img.h, img.w) } else { (img.w, img.h) };
        let (mut lib_w, mut lib_h): (Option<u32>, Option<u32>) = (None, None);
        if let Some(le) = params.long_edge {
            if le == 0 { return None; }
            if dw >= dh { lib_w = Some(le); } else { lib_h = Some(le); }
        } else if let Some(se) = params.short_edge {
            if se == 0 { return None; }
            if dw <= dh { lib_w = Some(se); } else { lib_h = Some(se); }
        }
        return compute_stored_target(img.w, img.h, lib_w, lib_h, swapped, params.no_upscale);
    }
    if params.width.is_some() || params.height.is_some() {
        let req_w = params.width.filter(|&v| v != 0 || params.height.is_none());
        let req_h = params.height.filter(|&v| v != 0 || params.width.is_none());
        // zero values are treated as unset when the other is set; both zero -> no resize (handled in compute)
        return compute_stored_target(img.w, img.h, req_w, req_h, swapped, params.no_upscale);
    }
    None
}

pub fn maybe_resize(img: &Image, params: &Params, data: &[u8], fmt: Format) -> Image {
    match plan_resize(img, params, data, fmt) {
        Some((tw, th)) => resize_image(img, tw, th),
        None => img.clone_with_rgba(),
    }
}

// ---------- Quantization (median cut) ----------
pub fn quantize(img: &Image, max_colors: usize) -> (Vec<[u8; 4]>, Vec<u8>) {
    // histogram
    let mut hist: HashMap<u32, u64> = HashMap::new();
    for p in img.rgba.chunks_exact(4) {
        let key = u32::from_be_bytes([p[0], p[1], p[2], p[3]]);
        *hist.entry(key).or_insert(0) += 1;
    }
    let mut colors: Vec<(u32, u64)> = hist.into_iter().collect();
    // deterministic order: by count desc then key
    colors.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
