// ---------- Resize ----------
fn lanczos(x: f64) -> f64 {
    if x == 0.0 { return 1.0; }
    if x.abs() >= 3.0 { return 0.0; }
    let px = std::f64::consts::PI * x;
    (px.sin() / px) * ((px / 3.0).sin() / (px / 3.0))
}

pub fn resize_image(img: &Image, new_w: u32, new_h: u32) -> Image {
    if new_w == img.w && new_h == img.h { return img.clone_with_rgba(); }
    if new_w == 0 || new_h == 0 { return img.clone_with_rgba(); }
    let (sw, sh) = (img.w as usize, img.h as usize);
    let (dw, dh) = (new_w as usize, new_h as usize);
    // horizontal pass to dw x sh (f32)
    let mut horiz = vec![0f32; dw * sh * 4];
    let scale_x = sw as f64 / dw as f64;
    let support_x = if scale_x > 1.0 { 3.0 * scale_x } else { 3.0 };
    for dx in 0..dw {
        let center = (dx as f64 + 0.5) * scale_x - 0.5;
        let start = (center - support_x).ceil() as i64;
        let end = (center + support_x).floor() as i64;
        let mut weights: Vec<(usize, f64)> = Vec::new();
        let mut sum = 0.0;
        for sx in start..=end {
            if sx < 0 || sx >= sw as i64 { continue; }
            let wgt = lanczos((sx as f64 - center) / if scale_x > 1.0 { scale_x } else { 1.0 });
            if wgt != 0.0 { weights.push((sx as usize, wgt)); sum += wgt; }
        }
        if sum == 0.0 { continue; }
        for y in 0..sh {
            for ch in 0..4 {
                let mut acc = 0.0;
                for (sx, wgt) in &weights {
                    acc += img.rgba[(y * sw + sx) * 4 + ch] as f64 * wgt;
                }
                horiz[(y * dw + dx) * 4 + ch] = (acc / sum) as f32;
            }
        }
    }
    let mut out = vec![0u8; dw * dh * 4];
    let scale_y = sh as f64 / dh as f64;
    let support_y = if scale_y > 1.0 { 3.0 * scale_y } else { 3.0 };
    for dy in 0..dh {
        let center = (dy as f64 + 0.5) * scale_y - 0.5;
        let start = (center - support_y).ceil() as i64;
        let end = (center + support_y).floor() as i64;
        let mut weights: Vec<(usize, f64)> = Vec::new();
        let mut sum = 0.0;
        for sy in start..=end {
            if sy < 0 || sy >= sh as i64 { continue; }
            let wgt = lanczos((sy as f64 - center) / if scale_y > 1.0 { scale_y } else { 1.0 });
            if wgt != 0.0 { weights.push((sy as usize, wgt)); sum += wgt; }
        }
        if sum == 0.0 { continue; }
        for x in 0..dw {
            for ch in 0..4 {
                let mut acc = 0.0;
                for (sy, wgt) in &weights {
                    acc += horiz[(sy * dw + x) * 4 + ch] as f64 * wgt;
                }
                let v = acc / sum;
                out[(dy * dw + x) * 4 + ch] = v.round().clamp(0.0, 255.0) as u8;
            }
        }
    }
    let mut im = Image::new(new_w, new_h, out);
    im.gray_hint = img.gray_hint;
    im
