// EXIF orientation handling
pub fn exif_orientation(data: &[u8], fmt: Format) -> u16 {
    let tiff = extract_exif_tiff(data, fmt);
    if let Some(t) = tiff { return parse_tiff_orientation(&t); }
    1
}
fn parse_tiff_orientation(t: &[u8]) -> u16 {
    if t.len() < 8 { return 1; }
    let le = match &t[0..2] { b"II" => true, b"MM" => false, _ => return 1 };
    let read_u16 = |o: usize| -> Option<u16> {
        if o + 2 > t.len() { return None; }
        Some(if le { u16::from_le_bytes([t[o], t[o + 1]]) } else { u16::from_be_bytes([t[o], t[o + 1]]) })
    };
    let read_u32 = |o: usize| -> Option<u32> {
        if o + 4 > t.len() { return None; }
        Some(if le { u32::from_le_bytes([t[o], t[o + 1], t[o + 2], t[o + 3]]) } else { u32::from_be_bytes([t[o], t[o + 1], t[o + 2], t[o + 3]]) })
    };
    if read_u16(2) != Some(42) { return 1; }
    let ifd = match read_u32(4) { Some(v) => v as usize, None => return 1 };
    let count = match read_u16(ifd) { Some(v) => v as usize, None => return 1 };
    for i in 0..count {
        let e = ifd + 2 + i * 12;
        if e + 12 > t.len() { break; }
        if read_u16(e) == Some(274) {
            // value is in first two bytes of 4-byte value field (endian aware)
            if let Some(v) = read_u16(e + 8) { return v; }
        }
    }
    1
}
fn extract_exif_tiff(data: &[u8], fmt: Format) -> Option<Vec<u8>> {
    match fmt {
        Format::Jpeg => {
            let segs = parse_jpeg_segments(data);
            for (marker, payload) in segs {
                if marker == 0xE1 && payload.starts_with(b"Exif\x00\x00") { return Some(payload[6..].to_vec()); }
