        return compute_stored_target(img.w, img.h, req_w, req_h, swapped, params.no_upscale);
    }
    None
}

pub fn maybe_resize(img: &Image, params: &Params, data: &[u8], fmt: Format) -> Image {
    match plan_resize(img, params, data, fmt) {
        Some((tw, th)) => resize_image(img, tw, th),
