// ---------- TIFF encode ----------
fn encode_tiff(img: &Image) -> Vec<u8> {
    let has_alpha = img.has_alpha();
    let channels: u16 = if has_alpha { 4 } else { 3 };
    // pixel data: rows RGB(A)
    let mut pixels = Vec::with_capacity(img.w as usize * img.h as usize * channels as usize);
    for p in img.rgba.chunks_exact(4) {
        pixels.extend_from_slice(&p[0..3]);
        if has_alpha { pixels.push(p[3]); }
    }
    let comp = zlib_compress(&pixels, 6);
    // Layout: header 8, IFD at 8, data after IFD, extras after image data
    // Tags count
    let n_tags: usize = if has_alpha { 12 } else { 11 };
    let ifd_size = 2 + n_tags * 12 + 4;
    let strip_offset = 8 + ifd_size as u32;
    let after_strip = strip_offset + comp.len() as u32;
    // extra data: BitsPerSample (channels*2), XRes (8), YRes (8), SampleFormat (channels*2)
    let bits_off = after_strip;
    let xres_off = bits_off + channels as u32 * 2;
    let yres_off = xres_off + 8;
    let samplefmt_off = yres_off + 8;
    let _extra_end = samplefmt_off + channels as u32 * 2;
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"II"); out.extend_from_slice(&42u16.to_le_bytes()); out.extend_from_slice(&8u32.to_le_bytes());
    out.extend_from_slice(&(n_tags as u16).to_le_bytes());
    let mut tag = |out: &mut Vec<u8>, id: u16, typ: u16, count: u32, val: [u8; 4]| {
        out.extend_from_slice(&id.to_le_bytes()); out.extend_from_slice(&typ.to_le_bytes()); out.extend_from_slice(&count.to_le_bytes()); out.extend_from_slice(&val);
    };
    let val_u32 = |v: u32| v.to_le_bytes();
    let val_u16 = |v: u16| { let mut a = [0u8; 4]; a[0..2].copy_from_slice(&v.to_le_bytes()); a };
    tag(&mut out, 256, 4, 1, val_u32(img.w));
    tag(&mut out, 257, 4, 1, val_u32(img.h));
    tag(&mut out, 258, 3, channels as u32, val_u32(bits_off));
    tag(&mut out, 259, 3, 1, val_u16(8));
    tag(&mut out, 262, 3, 1, val_u16(2));
    tag(&mut out, 273, 4, 1, val_u32(strip_offset));
    tag(&mut out, 277, 3, 1, val_u16(channels));
    tag(&mut out, 278, 4, 1, val_u32(img.h));
    tag(&mut out, 279, 4, 1, val_u32(comp.len() as u32));
    tag(&mut out, 282, 5, 1, val_u32(xres_off));
    tag(&mut out, 283, 5, 1, val_u32(yres_off));
    tag(&mut out, 296, 3, 1, val_u16(1));
    if has_alpha {
        tag(&mut out, 338, 3, 1, val_u16(2));
        tag(&mut out, 339, 3, channels as u32, val_u32(samplefmt_off));
    } else {
        tag(&mut out, 339, 3, channels as u32, val_u32(samplefmt_off));
    }
    out.extend_from_slice(&0u32.to_le_bytes()); // next IFD
    assert_eq!(out.len() as u32, strip_offset);
    out.extend_from_slice(&comp);
    // bits per sample
    for _ in 0..channels { out.extend_from_slice(&8u16.to_le_bytes()); }
    out.extend_from_slice(&72u32.to_le_bytes()); out.extend_from_slice(&1u32.to_le_bytes());
    out.extend_from_slice(&72u32.to_le_bytes()); out.extend_from_slice(&1u32.to_le_bytes());
    for _ in 0..channels { out.extend_from_slice(&1u16.to_le_bytes()); }
    out
}

// ---------- Metadata ----------
pub struct Metadata {
    pub exif_tiff: Option<Vec<u8>>, // TIFF blob (without Exif\0\0)
    pub icc: Option<Vec<u8>>,
    pub jpeg_app_segments: Vec<(u8, Vec<u8>)>, // (marker, payload) original JPEG segments in order
}
pub fn parse_jpeg_segments(data: &[u8]) -> Vec<(u8, Vec<u8>)> {
    let mut out = Vec::new();
    if data.len() < 2 || data[0] != 0xFF || data[1] != 0xD8 { return out; }
    let mut pos = 2usize;
    while pos + 4 <= data.len() {
        if data[pos] != 0xFF { break; }
        let marker = data[pos + 1];
        if marker == 0xDA || marker == 0xD9 { break; }
        if marker == 0xD8 || (0xD0..=0xD7).contains(&marker) { pos += 2; continue; }
        let len = u16::from_be_bytes([data[pos + 2], data[pos + 3]]) as usize;
        if len < 2 || pos + 2 + len > data.len() { break; }
        let payload = data[pos + 4..pos + 2 + len].to_vec();
        out.push((marker, payload));
        pos += 2 + len;
    }
    out
}
pub fn parse_webp_chunks(data: &[u8]) -> Vec<([u8; 4], Vec<u8>)> {
    let mut out = Vec::new();
    if data.len() < 12 { return out; }
    let mut pos = 12usize;
    while pos + 8 <= data.len() {
        let typ = [data[pos], data[pos + 1], data[pos + 2], data[pos + 3]];
        let len = u32::from_le_bytes([data[pos + 4], data[pos + 5], data[pos + 6], data[pos + 7]]) as usize;
        if pos + 8 + len > data.len() { break; }
        out.push((typ, data[pos + 8..pos + 8 + len].to_vec()));
        pos += 8 + len + (len & 1);
    }
    out
}
pub fn extract_metadata(data: &[u8], fmt: Format) -> Metadata {
    let mut md = Metadata { exif_tiff: None, icc: None, jpeg_app_segments: Vec::new() };
    match fmt {
        Format::Jpeg => {
            let segs = parse_jpeg_segments(data);
            md.jpeg_app_segments = segs.clone();
            let mut icc_parts: Vec<(u8, u8, Vec<u8>)> = Vec::new();
            for (marker, payload) in &segs {
                if *marker == 0xE1 && payload.starts_with(b"Exif\x00\x00") && md.exif_tiff.is_none() {
                    md.exif_tiff = Some(payload[6..].to_vec());
                }
                if *marker == 0xE2 && payload.starts_with(b"ICC_PROFILE\x00") && payload.len() > 14 {
                    icc_parts.push((payload[12], payload[13], payload[14..].to_vec()));
                }
            }
            if !icc_parts.is_empty() {
                icc_parts.sort_by_key(|p| p.0);
                let mut icc = Vec::new();
                for (_, _, part) in icc_parts { icc.extend_from_slice(&part); }
                md.icc = Some(icc);
            }
        }
        Format::Png => {
            if let Ok(info) = parse_png(data) {
                for (typ, cdata) in &info.chunks {
                    if typ == "eXIf" && md.exif_tiff.is_none() { md.exif_tiff = Some(cdata.clone()); }
                    if typ == "iCCP" {
                        // name\0 compression\0 compressed profile
                        if let Some(zero) = cdata.iter().position(|&b| b == 0) {
                            if zero + 1 < cdata.len() {
                                let comp = &cdata[zero + 2..];
                                // profile could be large; try several sizes
                                for guess in [65536usize, 1 << 20, 1 << 24] {
                                    if let Some(p) = zlib_uncompress(comp, guess) { md.icc = Some(p); break; }
                                }
                            }
                        }
                    }
                }
            }
        }
        Format::Webp => {
            for (typ, payload) in parse_webp_chunks(data) {
                if &typ == b"EXIF" && md.exif_tiff.is_none() { md.exif_tiff = Some(payload.clone()); }
                if &typ == b"ICCP" && md.icc.is_none() { md.icc = Some(payload.clone()); }
            }
        }
        _ => {}
    }
    md
}

fn jpeg_insert_metadata(jpeg: &[u8], md: &Metadata, keep_exif: bool, include_icc: bool, is_jpeg_source: bool) -> Vec<u8> {
    let mut inserts: Vec<u8> = Vec::new();
    if include_icc {
        if let Some(icc) = &md.icc {
            // split into APP2 segments max 65519 data? use 65000
            let chunks: Vec<&[u8]> = icc.chunks(65000).collect();
            let total = chunks.len() as u8;
            for (i, ch) in chunks.iter().enumerate() {
                let mut payload = Vec::new();
                payload.extend_from_slice(b"ICC_PROFILE\x00");
                payload.push((i + 1) as u8); payload.push(total);
                payload.extend_from_slice(ch);
                inserts.extend_from_slice(&[0xFF, 0xE2]);
                inserts.extend_from_slice(&((payload.len() + 2) as u16).to_be_bytes());
                inserts.extend_from_slice(&payload);
            }
        }
    }
    if keep_exif {
        if is_jpeg_source {
            // Copy original APP segments except APP2 (ICC handled separately) like mozjpeg marker copy
            for (marker, payload) in &md.jpeg_app_segments {
                if (0xE0..=0xEF).contains(marker) && *marker != 0xE2 {
                    inserts.extend_from_slice(&[0xFF, *marker]);
                    inserts.extend_from_slice(&((payload.len() + 2) as u16).to_be_bytes());
                    inserts.extend_from_slice(payload);
                }
            }
        } else if let Some(tiff) = &md.exif_tiff {
            let mut payload = Vec::new();
            payload.extend_from_slice(b"Exif\x00\x00");
            payload.extend_from_slice(tiff);
            inserts.extend_from_slice(&[0xFF, 0xE1]);
            inserts.extend_from_slice(&((payload.len() + 2) as u16).to_be_bytes());
            inserts.extend_from_slice(&payload);
        }
    }
    if inserts.is_empty() { return jpeg.to_vec(); }
    if jpeg.len() < 2 { return jpeg.to_vec(); }
    // Insert after the first segment if it is APP0, otherwise right after SOI
    let mut insert_pos = 2usize;
    if jpeg.len() >= 4 && jpeg[2] == 0xFF && jpeg[3] == 0xE0 {
        if jpeg.len() >= 6 {
            let len = u16::from_be_bytes([jpeg[4], jpeg[5]]) as usize;
            insert_pos = 2 + 2 + len;
            if insert_pos > jpeg.len() { insert_pos = 2; }
        }
    }
    let mut out = Vec::with_capacity(jpeg.len() + inserts.len());
    out.extend_from_slice(&jpeg[..insert_pos]);
    out.extend_from_slice(&inserts);
    out.extend_from_slice(&jpeg[insert_pos..]);
    out
}

fn webp_insert_metadata(webp: &[u8], img: &Image, md: &Metadata, keep_exif: bool, include_icc: bool) -> Vec<u8> {
    let exif = if keep_exif { md.exif_tiff.as_ref() } else { None };
    let icc = if include_icc { md.icc.as_ref() } else { None };
    if exif.is_none() && icc.is_none() { return webp.to_vec(); }
    if webp.len() < 12 { return webp.to_vec(); }
    // Parse existing frame chunk(s)
    let chunks = parse_webp_chunks(webp);
    let has_vp8x = chunks.iter().any(|(t, _)| t == b"VP8X");
    let mut feature: u8 = 0;
    if icc.is_some() { feature |= 0x20; }
    if img.has_alpha() { feature |= 0x10; }
    if exif.is_some() { feature |= 0x08; }
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"RIFF"); out.extend_from_slice(&[0, 0, 0, 0]); out.extend_from_slice(b"WEBP");
    if !has_vp8x {
        let mut vp8x = Vec::new();
        vp8x.push(feature); vp8x.extend_from_slice(&[0, 0, 0]);
        vp8x.extend_from_slice(&(img.w - 1).to_le_bytes()[0..3]);
        vp8x.extend_from_slice(&(img.h - 1).to_le_bytes()[0..3]);
        out.extend_from_slice(b"VP8X"); out.extend_from_slice(&(vp8x.len() as u32).to_le_bytes()); out.extend_from_slice(&vp8x);
        if vp8x.len() % 2 == 1 { out.push(0); }
    }
    // copy original chunks except VP8X (if we added/replacing) and EXIF/ICCP (re-added fresher below)
    for (typ, payload) in &chunks {
        if has_vp8x == false && (typ == b"EXIF" || typ == b"ICCP") { continue; }
        if has_vp8x && (typ == b"VP8X") {
            // keep original VP8X but patch feature bits
            let mut p = payload.clone();
            if !p.is_empty() { p[0] |= feature; }
            out.extend_from_slice(typ); out.extend_from_slice(&(p.len() as u32).to_le_bytes()); out.extend_from_slice(&p);
            if p.len() % 2 == 1 { out.push(0); }
            continue;
        }
        if typ == b"EXIF" || typ == b"ICCP" { continue; }
        out.extend_from_slice(typ); out.extend_from_slice(&(payload.len() as u32).to_le_bytes()); out.extend_from_slice(payload);
        if payload.len() % 2 == 1 { out.push(0); }
    }
    if let Some(icc) = icc {
        out.extend_from_slice(b"ICCP"); out.extend_from_slice(&(icc.len() as u32).to_le_bytes()); out.extend_from_slice(icc);
        if icc.len() % 2 == 1 { out.push(0); }
    }
    if let Some(exif) = exif {
        out.extend_from_slice(b"EXIF"); out.extend_from_slice(&(exif.len() as u32).to_le_bytes()); out.extend_from_slice(exif);
        if exif.len() % 2 == 1 { out.push(0); }
    }
    let riff_size = (out.len() - 8) as u32;
    out[4..8].copy_from_slice(&riff_size.to_le_bytes());
    out
}

fn png_insert_chunks(png: &[u8], md: &Metadata, keep_exif: bool, include_icc: bool) -> Vec<u8> {
    if !keep_exif && !include_icc { return png.to_vec(); }
    // Insert after IHDR chunk (8 + 25 = 33 typically)
    if png.len() < 33 { return png.to_vec(); }
    let mut inserts: Vec<u8> = Vec::new();
    if include_icc {
        if let Some(icc) = &md.icc {
            let mut d = Vec::new();
            d.extend_from_slice(b"FakeICC\x00\x00");
            d.extend_from_slice(&zlib_compress(icc, 6));
            png_chunk(&mut inserts, b"iCCP", &d);
        }
    }
    if keep_exif {
        if let Some(tiff) = &md.exif_tiff {
            png_chunk(&mut inserts, b"eXIf", tiff);
        }
    }
    if inserts.is_empty() { return png.to_vec(); }
    let mut out = Vec::new();
    out.extend_from_slice(&png[..33]);
    out.extend_from_slice(&inserts);
    out.extend_from_slice(&png[33..]);
    out
}

// ---------- Decode dispatch ----------
pub enum Decoded {
    Still(Image),
    Gif(GifFile),
}
pub fn decode_input(data: &[u8], fmt: Format) -> Result<Decoded, CompError> {
    match fmt {
        Format::Jpeg => Ok(Decoded::Still(decode_jpeg(data)?)),
        Format::Png => Ok(Decoded::Still(decode_png(data)?)),
        Format::Webp => Ok(Decoded::Still(decode_webp(data)?)),
        Format::Gif => Ok(Decoded::Gif(decode_gif(data)?)),
        Format::Tiff => Err(CompError::new("unsupported format", 20404)),
    }
}
fn still_image(dec: &Decoded) -> Image {
    match dec {
        Decoded::Still(i) => i.clone_with_rgba(),
        Decoded::Gif(g) => {
            if let Some(first) = g.composited.first() { first.clone_with_rgba() }
            else { Image::new(g.w as u32, g.h as u32, vec![0; g.w as usize * g.h as usize * 4]) }
        }
    }
}

// ---------- Encoding dispatch ----------
fn png_level(params: &Params) -> i32 {
    if params.zopfli { return 9; }
    match params.png_opt_level { 0 => 2, 1 => 3, 2 => 5, 3 => 6, 4 => 7, 5 => 8, _ => 9 }
}

fn encode_still_to_format(img: &Image, target: Format, mode_quality: Option<u32>, lossless: bool, params: &Params, md: &Metadata, source_fmt: Format) -> Result<Vec<u8>, CompError> {
    match target {
        Format::Jpeg => {
            let q = if lossless { 85 } else { mode_quality.unwrap_or(80) };
            let mut bytes = encode_jpeg(img, q, params)?;
            let include_icc = params.exif || (source_fmt == Format::Jpeg && !params.strip_icc && params.format == OutFormat::Original);
            bytes = jpeg_insert_metadata(&bytes, md, params.exif, include_icc, source_fmt == Format::Jpeg);
            Ok(bytes)
        }
        Format::Png => {
            if lossless {
                let bytes = encode_png_rgba(img, None, png_level(params), &[]);
                let bytes = png_insert_chunks(&bytes, md, params.exif, params.exif);
                Ok(bytes)
            } else {
                let q = mode_quality.unwrap_or(80);
                let mc = max_colors_for_quality(q);
                let (pal, idx) = quantize(img, mc);
                let pal4: Vec<[u8; 4]> = pal;
                let bytes = encode_png_rgba(img, Some((pal4, idx)), 9, &[]);
                let bytes = png_insert_chunks(&bytes, md, params.exif, params.exif);
                Ok(bytes)
            }
        }
        Format::Webp => {
            let mut bytes = if lossless {
                encode_webp(img, 0, true)?
            } else {
                encode_webp(img, mode_quality.unwrap_or(80), false)?
            };
            let include_icc = params.exif;
            bytes = webp_insert_metadata(&bytes, img, md, params.exif, include_icc);
            Ok(bytes)
        }
        Format::Gif => {
            let q = if lossless { 100 } else { mode_quality.unwrap_or(80) };
            let frame = gif_frame_from_image(img, q);
            Ok(encode_gif_frames(img.w as u16, img.h as u16, &[frame], None))
        }
        Format::Tiff => Ok(encode_tiff(img)),
    }
}

fn gif_frame_from_image(img: &Image, q: u32) -> GifFrame {
    // If image has transparency, reserve handling: quantize RGBA but force transparent pixels to a dedicated index
    let has_trans = img.rgba.chunks_exact(4).any(|p| p[3] < 128);
    if !has_trans {
        let mc = if q >= 100 { 256 } else { max_colors_for_quality(q) };
        let (pal_rgba, indices) = quantize(img, mc);
        let palette: Vec<[u8; 3]> = pal_rgba.iter().map(|c| [c[0], c[1], c[2]]).collect();
        return GifFrame { x: 0, y: 0, w: img.w as u16, h: img.h as u16, indices, palette, delay_cs: 0, disposal: 0, trans_idx: None };
    }
    // transparent path: build image where transparent pixels are colored (0,0,0,0) and quantize with a dedicated slot handled by quantizer alpha
    let mc = if q >= 100 { 256 } else { max_colors_for_quality(q) };
    let (pal_rgba, mut indices) = quantize(img, mc);
    // find palette entry closest to transparent (alpha lowest). Map fully transparent pixels to it and set its alpha index transparent.
    let mut trans_idx: Option<u8> = None;
    let mut palette: Vec<[u8; 3]> = Vec::new();
    for (i, c) in pal_rgba.iter().enumerate() {
        palette.push([c[0], c[1], c[2]]);
        if c[3] < 128 && trans_idx.is_none() { trans_idx = Some(i as u8); }
    }
    if let Some(ti) = trans_idx {
        for (i, p) in img.rgba.chunks_exact(4).enumerate() {
            if p[3] < 128 { indices[i] = ti; }
        }
    }
    GifFrame { x: 0, y: 0, w: img.w as u16, h: img.h as u16, indices, palette, delay_cs: 0, disposal: 0, trans_idx }
}

fn encode_gif_lossy_or_lossless(g: &GifFile, q: Option<u32>, lossless: bool, params: &Params, data: &[u8]) -> Result<Vec<u8>, CompError> {
    // resizing check happens at a higher level; here canvas/frames are assumed already final-sized
    let _ = params; let _ = data;
    if lossless || q == Some(100) {
        // re-encode original frames with their palettes
        return Ok(encode_gif_frames(g.w, g.h, &g.frames, g.loop_count));
    }
    let quality = q.unwrap_or(80);
    if quality >= 100 {
        return Ok(encode_gif_frames(g.w, g.h, &g.frames, g.loop_count));
    }
    let mc = max_colors_for_quality(quality);
    let mut frames_out: Vec<GifFrame> = Vec::new();
    for fr in &g.frames {
        // Build RGBA image of the frame rect
        let fw = fr.w as usize; let fh = fr.h as usize;
        let mut rgba = vec![0u8; fw * fh * 4];
        for (i, &idx) in fr.indices.iter().enumerate() {
            if Some(idx) == fr.trans_idx {
                rgba[i * 4 + 3] = 0;
            } else {
                let c = fr.palette.get(idx as usize).copied().unwrap_or([0, 0, 0]);
                rgba[i * 4] = c[0]; rgba[i * 4 + 1] = c[1]; rgba[i * 4 + 2] = c[2]; rgba[i * 4 + 3] = 255;
            }
        }
        let img = Image::new(fr.w as u32, fr.h as u32, rgba);
        // If original color count (nontransparent unique) <= mc, keep frame as-is
        let mut uniq = std::collections::HashSet::new();
        for p in img.rgba.chunks_exact(4) { uniq.insert(u32::from_be_bytes([p[0], p[1], p[2], p[3]])); }
        if uniq.len() <= mc && fr.palette.len() <= 256 {
            frames_out.push(fr.clone());
            continue;
        }
        let mut nf = gif_frame_from_image(&img, quality);
        nf.x = fr.x; nf.y = fr.y; nf.delay_cs = fr.delay_cs; nf.disposal = fr.disposal;
        // preserve transparency if original had it and new frame lost it
        if fr.trans_idx.is_some() && nf.trans_idx.is_none() {
            // gif_frame_from_image handles alpha<128; original transparent pixels are alpha0 in img so should be handled
        }
        frames_out.push(nf);
    }
    Ok(encode_gif_frames(g.w, g.h, &frames_out, g.loop_count))
}

// PNG lossless special recompression
fn png_lossless_recompress(data: &[u8], params: &Params) -> Result<Vec<u8>, CompError> {
    let info = parse_png(data)?;
    let expected = png_raw_size(&info).unwrap_or(0);
    if expected == 0 { return Ok(data.to_vec()); }
    let raw = match zlib_uncompress(&info.raw_idat, expected) {
        Some(r) => r,
        None => return Ok(data.to_vec()),
    };
    let level = if params.zopfli { 9 } else { png_level(params) };
    let comp = zlib_compress(&raw, level);
    // Rebuild: preserve chunk order; replace IDAT segments with one IDAT at first IDAT position
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    let mut idat_written = false;
    for (typ, cdata) in &info.chunks {
        if typ == "IDAT" {
            if !idat_written { png_chunk(&mut out, b"IDAT", &comp); idat_written = true; }
            continue;
        }
        let mut tb = [0u8; 4]; tb.copy_from_slice(&typ.as_bytes()[0..4]);
        png_chunk(&mut out, &tb, cdata);
    }
    if out.len() < data.len() { Ok(out) } else { Ok(data.to_vec()) }
}

// ---------- Main compress / convert ----------
pub fn compress(data: &[u8], detected: Format, params: &Params) -> Result<Vec<u8>, CompError> {
    let md = extract_metadata(data, detected);
    let is_lossless = params.lossless;
    let quality = params.quality;
    // MAX SIZE handled by caller? compress() may be called also from max-size original path via compress_to_max_size.
    // Here: quality / lossless only.
    match detected {
        Format::Jpeg => {
            // Special: zero dims handled by decode
            if is_lossless {
                // if resize needed, we must decode and resize then encode.
                if has_resize(params) {
                    let img = match decode_jpeg(data) {
                        Ok(i) => i,
                        Err(e) => { jpeg_error_side_effect(&e); return Err(e); }
                    };
                    let img2 = maybe_resize(&img, params, data, detected);
                    let mut bytes = encode_lossless_pixel_jpeg(&img2, params)?;
                    let include_icc = params.exif || !params.strip_icc;
                    bytes = jpeg_insert_metadata(&bytes, &md, params.exif, include_icc, true);
                    return Ok(bytes);
                }
                return match transcode_jpeg(data, params) {
                    Ok(mut bytes) => {
                        let include_icc = params.exif || !params.strip_icc;
                        bytes = jpeg_insert_metadata(&bytes, &md, params.exif, include_icc, true);
                        // transcode already carries JFIF etc; inserting APP duplicates from source may double JFIFs when exif.
                        // To avoid triple JFIF duplication in -e case we keep the result of insert (it adds original APPs like original does)
                        Ok(bytes)
                    }
                    Err(e) => { jpeg_error_side_effect(&e); Err(e) }
                };
            }
            let img = match decode_jpeg(data) { Ok(i) => i, Err(e) => { jpeg_error_side_effect(&e); return Err(e); } };
            let img2 = maybe_resize(&img, params, data, detected);
            let q = quality.unwrap_or(80);
            let mut bytes = match encode_jpeg(&img2, q, params) { Ok(b) => b, Err(e) => { jpeg_error_side_effect(&e); return Err(e); } };
            let include_icc = params.exif || !params.strip_icc;
            bytes = jpeg_insert_metadata(&bytes, &md, params.exif, include_icc, true);
            Ok(bytes)
        }
        Format::Png => {
            if is_lossless && !has_resize(params) {
                return png_lossless_recompress(data, params);
            }
            let img = decode_png(data)?;
            let img2 = maybe_resize(&img, params, data, detected);
            if is_lossless {
                let bytes = encode_png_rgba(&img2, None, png_level(params), &[]);
                return Ok(bytes);
            }
            let q = quality.unwrap_or(80);
            let mc = max_colors_for_quality(q);
            let (pal, idx) = quantize(&img2, mc);
            Ok(encode_png_rgba(&img2, Some((pal, idx)), 9, &[]))
        }
        Format::Webp => {
            if is_lossless && !has_resize(params) {
                let img = decode_webp(data)?;
                let mut bytes = encode_webp(&img, 0, true)?;
                bytes = webp_insert_metadata(&bytes, &img, &md, params.exif, params.exif);
                return Ok(bytes);
            }
            let img = decode_webp(data)?;
            let img2 = maybe_resize(&img, params, data, detected);
            if is_lossless {
                let mut bytes = encode_webp(&img2, 0, true)?;
                bytes = webp_insert_metadata(&bytes, &img2, &md, params.exif, params.exif);
                return Ok(bytes);
            }
            let q = quality.unwrap_or(80);
            let mut bytes = encode_webp(&img2, q, false)?;
            bytes = webp_insert_metadata(&bytes, &img2, &md, params.exif, params.exif);
            Ok(bytes)
        }
        Format::Gif => {
            let g = decode_gif(data)?;
            if has_resize(params) {
                // composite, resize each snapshot, encode frames as full frames
                let mut resized_frames: Vec<GifFrame> = Vec::new();
                // determine target size from first snapshot plan
                let first = still_image(&Decoded::Gif(g.clone()));
                let target = plan_resize(&first, params, data, detected);
                for snap in &g.composited {
                    let resized = match target { Some((tw, th)) => resize_image(snap, tw, th), None => snap.clone_with_rgba() };
                    let q = if is_lossless { 100 } else { quality.unwrap_or(80) };
                    let mut fr = gif_frame_from_image(&resized, q);
                    // delay/disposal from corresponding original frame
                    let idx = resized_frames.len();
                    if let Some(of) = g.frames.get(idx) { fr.delay_cs = of.delay_cs; fr.disposal = 1; }
                    resized_frames.push(fr);
                }
                let (nw, nh) = match target { Some(t) => t, None => (g.w as u32, g.h as u32) };
                return Ok(encode_gif_frames(nw as u16, nh as u16, &resized_frames, g.loop_count));
            }
            return encode_gif_lossy_or_lossless(&g, quality, is_lossless, params, data);
        }
        Format::Tiff => Err(CompError::new("unsupported format", 10404)),
    }
}

fn encode_lossless_pixel_jpeg(img: &Image, params: &Params) -> Result<Vec<u8>, CompError> {
    // decode+resize lossless fallback: quality 100, 4:4:4
    let mut rgb = Vec::with_capacity((img.w * img.h * 3) as usize);
    for px in img.rgba.chunks_exact(4) { rgb.extend_from_slice(&px[0..3]); }
    unsafe {
        let mut out: *mut u8 = std::ptr::null_mut(); let mut out_len: u64 = 0; let mut code: i32 = 0;
        let mut msg = vec![0u8; 512];
        let progressive = if params.jpeg_baseline { 0 } else { 1 };
        let rc = cj_encode(rgb.as_ptr(), img.w as i32, img.h as i32, 3, 100, progressive, 0, &mut out, &mut out_len, &mut code, msg.as_mut_ptr(), msg.len() as u64);
        if rc != 0 { return Err(CompError::new(&format!("Internal JPEG error: {}", code), 20104)); }
        let bytes = std::slice::from_raw_parts(out, out_len as usize).to_vec();
        free(out as *mut c_void);
        Ok(bytes)
    }
}

fn jpeg_error_side_effect(e: &CompError) {
    // Original prints a caught panic to stderr for JPEG errors in same-format path
    if e.code == 20104 {
        if let Some(code_str) = e.message.strip_prefix("Internal JPEG error: ") {
            if let Ok(code) = code_str.parse::<i32>() { jpeg_panic_stderr(code); return; }
        }
        jpeg_panic_stderr(0);
    }
}

pub fn has_resize(params: &Params) -> bool {
    (params.width.is_some() && params.width != Some(0))
        || (params.height.is_some() && params.height != Some(0))
        || (params.long_edge.is_some() && params.long_edge != Some(0))
        || (params.short_edge.is_some() && params.short_edge != Some(0))
}

fn decode_for_convert(data: &[u8], detected: Format) -> Result<Decoded, CompError> {
    // mimic conversion path error formats
    match decode_input(data, detected) {
        Ok(d) => Ok(d),
        Err(e) => Err(convert_decode_error(data, detected, e)),
    }
}

fn convert_decode_error(data: &[u8], detected: Format, orig: CompError) -> CompError {
    let full = match detected {
        Format::Png => {
            // check strict signature
            if data.len() < 8 || &data[0..8] != b"\x89PNG\r\n\x1a\n" {
                "The image format could not be determined".to_string()
            } else if data.len() >= 16 && &data[12..16] != b"IHDR" {
                let t = &data[12..16];
                let fmt_byte = |b: u8| -> String {
                    if b == 0 { "\\0".to_string() } else if (32..127).contains(&b) { (b as char).to_string() } else { format!("\\u{{{}}}", b) }
                };
                let type_str: String = t.iter().map(|&b| fmt_byte(b)).collect();
                format!("Format error decoding Png: ChunkType {{ type: {}, critical: {}, private: {}, reserved: false, safecopy: false }} chunk appeared before IHDR chunk", type_str, (t[0] & 32) == 0, (t[1] & 32) != 0)
            } else {
                format!("Format error decoding Png: {}", orig.message)
            }
        }
        Format::Jpeg => {
            // look for marker with invalid segment length
            let mut msg: Option<String> = None;
            if data.len() >= 4 && data[0] == 0xFF && data[1] == 0xD8 {
                let mut pos = 2usize;
                while pos + 4 <= data.len() {
                    if data[pos] != 0xFF { break; }
                    let m = data[pos + 1];
                    if m == 0xDA { break; }
                    let len = u16::from_be_bytes([data[pos + 2], data[pos + 3]]);
                    if len < 2 { msg = Some(format!("Found a marker with invalid length:{}\\n", len)); break; }
                    pos += 2 + len as usize;
                }
            }
            match msg {
                Some(m) => format!("Format error decoding Jpeg: \"{}\"", m),
                None => format!("Format error decoding Jpeg: \"{}\"", orig.message),
            }
        }
        Format::Webp => {
            if data.len() >= 16 {
                let chunk = &data[12..16];
                if chunk != b"VP8 " && chunk != b"VP8L" && chunk != b"VP8X" {
                    format!("Format error decoding WebP: Invalid Chunk header: [{}, {}, {}, {}]", chunk[0], chunk[1], chunk[2], chunk[3])
                } else {
                    "Format error decoding WebP: The image format could not be determined".to_string()
                }
            } else { "The image format could not be determined".to_string() }
        }
        Format::Gif => {
            if data.len() < 6 || (&data[0..6] != b"GIF87a" && &data[0..6] != b"GIF89a") {
                "The image format could not be determined".to_string()
            } else {
                format!("Format error decoding Gif: {}", gif_image_crate_detail(data))
            }
        }
        Format::Tiff => "The image format could not be determined".to_string(),
    };
    let mut e = CompError::new(&full, 10403);
    e.convert_message = Some(format!("Error compressing file: {} [10403]", full));
    e
}
fn gif_image_crate_detail(data: &[u8]) -> String {
    // zero-size gif with GCT? generic unknown block
    if data.len() >= 14 {
        // If after header+GCT there is a zero block type byte or truncated, image crate says unknown block type
        return "unknown block type encountered".to_string();
    }
    "unknown block type encountered".to_string()
}

pub fn convert(data: &[u8], detected: Format, target: Format, params: &Params) -> Result<Vec<u8>, CompError> {
    let md = extract_metadata(data, detected);
    let dec = decode_for_convert(data, detected)?;
    // GIF resize / still handling: for conversion we use still (first composited) unless target is gif and source gif? (then it's same format error earlier)
    let mut img = still_image(&dec);
    // GIF source with resize: still image should be resized from canvas dims; plan_resize uses img w/h and exif (gif has none)
    img = maybe_resize(&img, params, data, detected);
    if params.lossless {
        return encode_still_to_format(&img, target, None, true, params, &md, detected);
    }
    let q = params.quality.unwrap_or(80);
    encode_still_to_format(&img, target, Some(q), false, params, &md, detected)
}

pub fn compress_to_max_size(data: &[u8], detected: Format, target: Format, max_size: u64, params: &Params) -> Result<Vec<u8>, CompError> {
    // Build a params clone for trial encodings (quality mode)
    // If target is TIFF, quality does not affect; just encode once (original encodes through quality seeking on source, but we approximate)
    if target == Format::Tiff {
        let dec = decode_input(data, detected)?;
        let mut img = still_image(&dec);
        img = maybe_resize(&img, params, data, detected);
        let md = extract_metadata(data, detected);
        return encode_still_to_format(&img, target, Some(80), false, params, &md, detected);
    }
    // Special lossless-like formats where quality=1..100 search applies
    let mut trial_params = params.clone();
    trial_params.max_size = None;
    trial_params.lossless = false;
    // helper to encode at quality q to target
    let encode_at = |q: u32, tp: &Params| -> Result<Vec<u8>, CompError> {
        let mut p = tp.clone();
        p.quality = Some(q);
        if target == detected && params.format == OutFormat::Original {
            compress_with_quality(data, detected, &p)
        } else {
            // conversion to target
            convert(data, detected, target, &p)
        }
    };
    // If even q=100 fits, use it
    // Search: evaluate qualities with a step-down then refine approach similar to observed.
    // First try 100 down by 10
    let mut best: Option<Vec<u8>> = None;
    let mut q: i32 = 100;
    let mut found_fit_q: Option<u32> = None;
    while q >= 1 {
        let bytes = encode_at(q as u32, &trial_params)?;
        if (bytes.len() as u64) <= max_size { found_fit_q = Some(q as u32); best = Some(bytes); break; }
        if q == 1 { best = Some(bytes); found_fit_q = None; break; }
        q -= 10;
        if q < 1 { q = 1; }
    }
    if let Some(fq) = found_fit_q {
        // refine upward by 1 while fits (max 9 steps from a multiple of 10, except when fq==100)
        let mut cur_q = fq;
        let mut cur = best.unwrap();
        while cur_q < 100 {
            let nq = cur_q + 1;
            let bytes = encode_at(nq, &trial_params)?;
            if (bytes.len() as u64) <= max_size { cur = bytes; cur_q = nq; } else { break; }
        }
        return Ok(cur);
    }
    // No fit even at q=1 after step loop: best holds q=1 result
    match best { Some(b) => Ok(b), None => Err(CompError::new("could not compress to max size", 10400)) }
}

fn compress_with_quality(data: &[u8], detected: Format, params: &Params) -> Result<Vec<u8>, CompError> {
    let mut p = params.clone();
    p.lossless = false;
    p.max_size = None;
    compress(data, detected, &p)
}

