    if d[:2]==b'\xff\xd8':
        i=2
        while i<len(d)-1:
            if d[i]!=0xFF: i+=1; continue
            m=d[i+1]
            if m in (0xC0,0xC1,0xC2):
                h,w=struct.unpack(">HH",d[i+5:i+9]); return ("jpg",(w,h),hex(m))
            if m in (0xD8,0x01) or 0xD0<=m<=0xD7: i+=2; continue
            ln=struct.unpack(">H",d[i+2:i+4])[0]; i+=2+ln
        return ("jpg",None)
    if d[:3]==b'GIF': return ("gif",struct.unpack("<HH",d[6:10]))
    if d[:4]==b'RIFF' and d[8:12]==b'WEBP':
        typ=d[12:16]
        if typ==b'VP8 ': return ("webp",(struct.unpack("<H",d[26:28])[0]&0x3fff, struct.unpack("<H",d[28:30])[0]&0x3fff))
        if typ==b'VP8L': 
            b=d[21:26]; return ("webpL",(1+(b[0]|((b[1]&0x3f)<<8)), 1+(((b[1]>>6)|(b[2]<<2)|((b[3]&0xf)<<10)))))
        if typ==b'VP8X': return ("webpX",(1+(d[24]|d[25]<<8|d[26]<<16),1+(d[27]|d[28]<<8|d[29]<<16)))
        return ("webp",typ)
    if d[:2]==b'II' and d[2:4]==b'*\x00':
        off=struct.unpack("<I",d[4:8])[0]; cnt=struct.unpack("<H",d[off:off+2])[0]; tags={}
        for i in range(cnt):
            tag,typ,ct,val=struct.unpack("<HHI4s",d[off+2+i*12:off+2+i*12+12]); tags[tag]=struct.unpack("<I",val)[0] if typ==4 else struct.unpack("<H",val[:2])[0]
        return ("tiff",(tags.get(256),tags.get(257)),tags.get(259))
    return ("unknown",d[:8])
def run(exe,args,outdir):
    shutil.rmtree(outdir,ignore_errors=True)
    r=subprocess.run([exe]+args+["-o",outdir,"--verbose","3"],capture_output=True,text=True)
    files={}
    if os.path.exists(outdir):
        for root,_,fs in os.walk(outdir):
            for f in fs:
                p=os.path.join(root,f); files[os.path.relpath(p,outdir)]=(os.path.getsize(p),dim(p))
    status=[l.split(']')[0]+']' for l in r.stdout.splitlines() if l.startswith('[')]
    return (r.returncode,status,files, [l for l in r.stdout.splitlines() if l.startswith("Error") or l.startswith("File") or l.startswith("Insufficient")])
cases=[]
inputs=["/tmp/ref/p0.png","/tmp/ref/j0.JPG","/tmp/ref/w0.webp","/tmp/ref/g1.gif","/tmp/gen/alpha.png"]
for infile in inputs:
    for extra in [["-q","80"],["-q","0"],["-q","100"],["--lossless"],["--max-size","20000"],["-q","80","--width","100"],["-q","80","--height","77"],["-q","80","--long-edge","123"],["-q","80","--short-edge","55"],["-q","80","--width","5000"],["-q","80","--width","5000","--no-upscale"],["-q","80","--width","200","--height","50"]]:
        cases.append((extra,infile))
    for fmt in ["jpeg","png","gif","webp","tiff","original"]:
        cases.append((["-q","80","--format",fmt],infile))
        cases.append((["--lossless","--format",fmt],infile))
diffs=0
for extra,infile in cases:
    a=run(ORIG,extra+[infile],"/tmp/cmp_o")
    b=run(NEW,extra+[infile],"/tmp/cmp_n")
    # Compare status, file names and dimensions (not sizes)
    af={k:(v[1]) for k,v in a[2].items()}; bf={k:(v[1]) for k,v in b[2].items()}
    if a[0]!=b[0] or a[1]!=b[1] or af!=bf or (a[3]!=b[3] and False):
        diffs+=1; print("DIFF",extra,infile); print(" orig",a[0],a[1],af,a[3]); print(" new ",b[0],b[1],bf,b[3])
print("cases",len(cases),"diffs",diffs)
