import subprocess, shutil, os, re
ORIG="/tmp/origtest/executable"; NEW="/tmp/newtest/executable"
def norm(s,root): return s.replace(root,"{R}")
def compare(label,args,root_files=None,cwd=None):
    outs=[]
    for exe in [ORIG,NEW]:
        root="/tmp/scan_cmp"
        shutil.rmtree(root,ignore_errors=True); os.makedirs(root+"/in/sub/deep",exist_ok=True); os.makedirs(root+"/in/other",exist_ok=True)
        shutil.copy("/tmp/ref/p0.png",root+"/in/a.png"); shutil.copy("/tmp/ref/j0.JPG",root+"/in/b.jpg"); shutil.copy("/tmp/ref/w0.webp",root+"/in/sub/c.webp"); shutil.copy("/tmp/ref/p0.png",root+"/in/sub/d.png"); shutil.copy("/tmp/ref/g1.gif",root+"/in/sub/deep/e.gif"); shutil.copy("/tmp/ref/p0.png",root+"/in/other/a.png")
        if root_files:
            for name,src in root_files: shutil.copy(src,root+"/"+name)
        a=[x.replace("{R}",root) for x in args]
        r=subprocess.run([exe]+a,capture_output=True,text=True,cwd=cwd.replace("{R}",root) if cwd else None)
        files=[]
        if os.path.exists(root+"/out"):
            for rr,_,fs in os.walk(root+"/out"):
                for f in fs: files.append(os.path.relpath(os.path.join(rr,f),root+"/out"))
        # normalize status lines: keep [Success]/[Error]/[Skipped] with paths, strip size lines
        lines=[]
        for l in r.stdout.splitlines():
