use std::env;
use std::path::PathBuf;
use std::process::Command;

fn find_libjpeg() -> String {
    let candidates = [
        "/lib/x86_64-linux-gnu/libjpeg.so.8",
        "/usr/lib/x86_64-linux-gnu/libjpeg.so.8",
        "/lib/aarch64-linux-gnu/libjpeg.so.8",
        "/usr/lib/aarch64-linux-gnu/libjpeg.so.8",
        "/usr/lib/libjpeg.so.8",
        "/lib/libjpeg.so.8",
    ];
    for c in candidates {
        if PathBuf::from(c).exists() {
            return c.to_string();
        }
    }
    // Fallback to linker name (works if a development symlink exists)
    "jpeg".to_string()
}

fn main() {
    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
    let obj = out_dir.join("jpeghelper.o");
    let src = PathBuf::from("src/jpeghelper.c");
    println!("cargo:rerun-if-changed=src/jpeghelper.c");
    println!("cargo:rerun-if-changed=build.rs");
    let status = Command::new("cc")
        .args(["-O2", "-fPIC", "-c"])
        .arg(&src)
        .arg("-o")
        .arg(&obj)
        .status()
        .expect("failed to run cc for jpeg helper");
    if !status.success() {
        panic!("cc failed for jpeg helper");
    }
    let lib = out_dir.join("libjpeghelper.a");
    let status = Command::new("ar")
        .args(["rcs"])
        .arg(&lib)
        .arg(&obj)
        .status()
        .expect("failed to run ar");
    if !status.success() {
        panic!("ar failed");
    }
    println!("cargo:rustc-link-search=native={}", out_dir.display());
    println!("cargo:rustc-link-lib=static=jpeghelper");
    let jpeg = find_libjpeg();
    if jpeg == "jpeg" {
        println!("cargo:rustc-link-lib=jpeg");
    } else {
        println!("cargo:rustc-link-arg={}", jpeg);
    }
}
